e\n        }\n        this.escHandler = this.escHandler.bind(this);\n        //datepicker\n        this.openDatePicker = this.openDatePicker.bind(this);\n        this.closeDatePicker = this.closeDatePicker.bind(this);\n        this.dpKeyDownHandler = this.dpKeyDownHandler.bind(this);\n        this.handleCalendarIcon = this.handleCalendarIcon.bind(this);\n        //timepicker\n        this.openTimePicker = this.openTimePicker.bind(this);\n        this.closeTimePicker = this.closeTimePicker.bind(this);\n        this.tpKeyDownHandler = this.tpKeyDownHandler.bind(this);\n        this.handleClockIcon = this.handleClockIcon.bind(this);\n\n\n\n    }\n\n    componentDidMount() {\n        document.addEventListener(\"keydown\", this.escHandler, false);\n        this.datepicker.input.ariaLive = \"polite\";\n        this.timepicker.input.ariaLive = \"polite\";\n\n        this.updateState()\n    }\n\n    componentDidUpdate(prevProps) {\n        if (this.props.attributes.availability !== prevProps.attributes.availability) {\n            this.updateState()\n        }\n    }\n\n    updateState(name, date) {\n        let startTime = moment(this.props.attributes.availability.startTime, 'HH:mm');\n        let startDate = moment.unix(this.props.attributes.availability.startDate)\n            .set({\"h\": startTime.hours(), \"m\": startTime.minutes()})\n            .toDate()\n        let endTime = moment(this.props.attributes.availability.endTime, 'HH:mm');\n        let endDate = moment.unix(this.props.attributes.availability.endDate)\n            .set({\"h\": endTime.hours(), \"m\": endTime.minutes()})\n            .toDate()\n\n        let selectedDate = (\"startDate\" == this.props.name) ? startDate : endDate\n\n        if (name && date) {\n            startDate = (\"startDate\" == name) ? date.startOf('day') : startDate;\n            endDate = (\"endDate\" == name) ? date.startOf('day') : endDate;\n            selectedDate = date\n        }\n        this.setState({\n            availability: this.props.attributes.availability,\n            availabilityList: this.props.attributes.availabilitylist,\n            selectedDate: selectedDate\n        }, () => {\n            this.setExcludeTimesForDay()\n        })\n    }\n\n    setClassNameForSelectedWeekDay(className, date) {\n        if (this.isWeekDaySelected(date) &&\n            this.isDateInAvailabilityRange(date)\n        ) {\n            className = `${className} day__selected__weekday__${this.state.availability.type}`; \n        }\n        return className\n    }\n\n    isDateInAvailabilityRange(date) {\n        return (\n            date <= moment.unix(this.state.availability.endDate).toDate() && \n            date >= moment.unix(this.state.availability.startDate).toDate()\n        )\n    }\n\n    isDateEqual(date1, date2) {\n        return (\n            date1.getDate() === date2.getDate() &&\n            date1.getMonth() === date2.getMonth() &&\n            date1.getFullYear() === date2.getFullYear()\n        )\n    }\n\n    isWeekDaySelected(date, availability)\n    {\n        const selectedAvailability = availability ? availability : this.state.availability\n        let isSelected = false;\n        for (const [key, value] of Object.entries(selectedAvailability.weekday)) {\n            weekDayList.map((weekday, index) => {\n                if ((index+1) == date.getDay() && weekday.value == key && value > 0) {\n                    isSelected = true; \n                }   \n            }) \n        } \n        return isSelected;\n    }\n\n    setExcludeTimesForDay() {\n        var times = []\n        this.state.availabilityList.map(availability => {\n            if (availability.id !== this.state.availability.id &&\n                availability.type == this.state.availability.type &&\n                this.isWeekDaySelected(this.state.selectedDate, availability)\n            ) {\n                const startTime = moment(availability.startTime, 'hh:mm')\n                    .add(this.state.availability.slotTimeInMinutes, \"m\");\n                const startOnDay = moment(this.state.selectedDate)\n                    .set({\"h\": startTime.hours(), \"m\": startTime.minutes()})\n                    .toDate()\n                \n                const endTime = moment(availability.endTime, 'hh:mm')\n                    .subtract(this.state.availability.slotTimeInMinutes, \"m\");\n                const endOnDay = moment(this.state.selectedDate)\n                    .set({\"h\": endTime.hours(), \"m\": endTime.minutes()})\n                    .toDate()\n               \n                var currentTime = new Date(startOnDay)\n                while (currentTime < endOnDay) {\n                    times = [...times, new Date(currentTime)]\n                    currentTime = moment(currentTime)\n                        .add(this.state.availability.slotTimeInMinutes, \"m\")\n                        .toDate()\n                }\n                times = [...times, endOnDay]\n            }\n        });\n        this.setState({excludeTimeList: times});\n    }\n\n    handleChange(name, date) {\n        if ('startDate' == name) {\n            if (this.state.availability.startDate != moment(date).startOf('day').unix()) {\n                this.props.onChange(\"startDate\", moment(date).unix());\n            }\n        }\n        if ('endDate' == name) {\n            if (this.state.availability.endDate != moment(date).startOf('day').unix()) {\n                this.props.onChange(\"endDate\", moment(date).unix());\n            }\n        }\n        this.closeDatePicker();\n    }\n\n    handleTimeChange(name, date) {\n        if ('startDate' == name) {\n            if (this.state.availability.startTime != moment(date).format('HH:mm')) {\n                this.props.onChange(\"startTime\", moment(date).format('HH:mm'));\n            }\n        }\n        if ('endDate' == name) {\n            if (this.state.availability.endTime != moment(date).format('HH:mm')) {\n                this.props.onChange(\"endTime\", moment(date).format('HH:mm'));\n            }\n        }\n        this.closeTimePicker();\n    }\n\n    escHandler(event) {\n        if (event.key === \"Escape\") {\n            this.closeDatePicker();\n            this.closeTimePicker();\n        }\n    }\n\n    dpKeyDownHandler(event) {\n        if (event.key === 'Enter') {\n            event.preventDefault()\n            this.openDatePicker() \n        }\n    }\n\n    tpKeyDownHandler(event) {\n        if (event.key === 'Enter') {\n            event.preventDefault()\n            this.openTimePicker() \n        }\n    }\n\n    handleCalendarIcon(event) {\n        event.preventDefault();\n        this.openDatePicker()\n        console.log(this.datepicker.input)\n        this.datepicker.input.focus();\n    }\n\n    handleClockIcon(event) {\n        event.preventDefault();\n        this.openTimePicker()\n        this.timepicker.input.focus();\n    }\n\n    openDatePicker() {\n        if (!this.props.attributes.disabled) {\n            this.setState({\n                datePickerIsOpen: true,\n            });\n        }\n    }\n\n    openTimePicker() {\n        if (!this.props.attributes.disabled) {\n            this.setState({\n                timePickerIsOpen: true,\n            });\n        }\n        \n    }\n\n    closeDatePicker() {\n        this.setState({\n            datePickerIsOpen: false,\n        });\n    }\n\n    closeTimePicker() {\n        this.setState({\n            timePickerIsOpen: false,\n        });\n    }\n\n    render() {\n        const dayClassName = (date) => {\n            let className = \"\";\n            className = this.setClassNameForSelectedWeekDay(className, date);\n            return className;\n        }\n\n        /*\n        const filterPassedTime = (time) => {\n            const currentDate = this.state.selectedDate;\n            const selectedDate = new Date(time);\n            return currentDate.getTime() < selectedDate.getTime();\n          };\n        \n        const isWeekday = date => {\n            const day = date.getDay();\n            return day !== 0 && day !== 6;\n        };\n        */\n\n        return (\n            <div className=\"grid\">\n                <div className=\"grid__item one-half\">\n                    <div className=\"form-group\">\n                        <Label \n                            attributes={{\"htmlFor\": this.props.attributes.id, \"className\": \"light\"}} \n                            value={\"startDate\" == this.props.name ? \"Datum von\" : \"Datum bis\" }>\n                        </Label>    \n                        <div className=\"controls add-date-picker\">\n                            <DatePicker \n                                todayButton=\"Heute\"\n                                locale=\"de\" \n                                className=\"form-control form-input\" \n                                id={this.props.attributes.id}\n                                ariaDescribedBy={\"help_\" + this.props.attributes.id}\n                                name={this.props.name}\n                                dateFormat=\"dd.MM.yyyy\" \n                                selected={this.state.selectedDate}\n                                onChange={date => {this.handleChange(this.props.name, date)}}\n                                minDate={this.state.minDate}\n                                //maxDate={repeat(this.state.availability.repeat) == 0 ? this.state.selectedDate : null}\n                                //filterDate={isWeekday}\n                                //excludeDates={this.state.excludeDateList}                   \n                                dayClassName={dayClassName}\n                                disabled={this.props.attributes.disabled}\n                                onInputClick={this.openDatePicker}\n                                onKeyDown={this.dpKeyDownHandler}\n                                onClickOutside={this.closeDatePicker}\n                                strictParsing={true}\n                                open={this.state.datePickerIsOpen}\n                                ref={(datepicker) => { this.datepicker = datepicker }} \n\n                            />\n                            <a aria-describedby={\"help_\" + this.props.attributes.id} href=\"#\" className=\"calendar-placement icon\" title={\"startDate\" == this.props.name ? \"Kalender Datum von öffnen\" : \"Kalender Datum bis öffnen\"} onClick={this.handleCalendarIcon} onKeyDown={this.dpKeyDownHandler}>\n                                <i className=\"far fa-calendar-alt\" alt={\"startDate\" == this.props.name ? \"Kalender Datum von öffnen\" : \"Kalender Datum bis öffnen\"} />\n                            </a>\n                        </div>\n                        <Description attributes={{ \"id\": \"help_\" + this.props.attributes.id }} value=\"Eingabe des Datums im Format TT.MM.YYYY\"></Description>\n                    </div>\n                </div>\n                <div className=\"grid__item one-half\">\n                    <div className=\"form-group\">\n                        <Label \n                            attributes={{\"htmlFor\": this.props.attributes.id + \"_time\", \"className\": \"light\"}} \n                            value={\"startDate\" == this.props.name ? \"Uhrzeit von\" : \"Uhrzeit bis\" }>\n                        </Label> \n                        <div className=\"controls add-date-picker\">\n                            <DatePicker\n                                name={this.props.name + \"_time\"}\n                                locale=\"de\"\n                                className=\"form-control form-input\" \n                                ariaDescribedBy={\"help_\" + this.props.attributes.id + \"_time\"}\n                                id={this.props.attributes.id + \"_time\"}\n                                selected={this.state.selectedDate}\n                                onChange={date => {this.handleTimeChange(this.props.name, date)}}\n                                showTimeSelect\n                                showTimeSelectOnly\n                                dateFormat=\"HH:mm\"\n                                timeFormat=\"HH:mm\"\n                                timeIntervals={this.state.availability.slotTimeInMinutes || 10}\n                                timeCaption=\"Uhrzeit\"\n                                minTime={this.state.minTime}\n                                maxTime={this.state.maxTime}\n                                excludeTimes={this.state.excludeTimeList}\n                                //filterTime={filterPassedTime}\n                                disabled={this.props.attributes.disabled}\n                                onInputClick={this.openTimePicker}\n                                onKeyDown={this.tpKeyDownHandler}\n                                onClickOutside={this.closeTimePicker}\n                                strictParsing={true}\n                                open={this.state.timePickerIsOpen}\n                                ref={(timepicker) => { this.timepicker = timepicker }} \n                            />\n                            <a href=\"#\" aria-describedby={\"help_\" + this.props.attributes.id + \"_time\"} className=\"calendar-placement icon\" title={\"startDate\" == this.props.name ? \"Uhrzeit von wählen\" : \"Uhrzeit bis wählen\"} onClick={this.handleClockIcon} onKeyDown={this.tpKeyDownHandler}>\n                                <i className=\"far fa-clock\" alt=\"Uhrzeitauswahl öffnen\" />\n                            </a>\n                        </div>\n                        <Description attributes={{ \"id\": \"help_\" + this.props.attributes.id + \"_time\" }} value=\"Eingabe der Uhrzeit im Format HH:MM\"></Description>\n                    </div>\n                </div>\n            </div>\n        )\n    }\n}\n\nAvailabilityDatePicker.propTypes = {\n    onChange: PropTypes.func,\n    attributes: PropTypes.object\n}\n\nexport default AvailabilityDatePicker","import React from 'react'\nimport PropTypes from 'prop-types'\n\nconst renderErrors = errors => Object.keys(errors).map(key => {\n    return (\n        <div key={errors[key].id}>\n            {errors[key].itemList.map((item, index) => {\n                return <div key={index}>{item[0].message}</div>\n            })}   \n        </div>\n    )\n})\n\nconst Errors = (props) => {\n    return (\n        Object.keys(props.errorList).length > 0 ? \n        <div className=\"message message--error\" role=\"alert\" aria-live=\"polite\">\n            <h3>Folgende Fehler sind bei der Prüfung Ihrer Eingaben aufgetreten:</h3>\n            {renderErrors(props.errorList)}\n        </div> : null\n    )\n}\n\nErrors.defaultProps = {\n    errorList: []\n}\n\nErrors.propTypes = {\n    errorList: PropTypes.object\n}\n\nexport default Errors\n","import React from 'react'\nimport PropTypes from 'prop-types'\nimport moment from 'moment'\n\nconst formatDate = date => {\n    const momentDate = moment(date)\n    return `${momentDate.format('DD.MM.YYYY')}`\n} \n\nconst renderConflictList = (conflictList) => {\n    let conflictDatesByMessage = [];\n    conflictList.map(collection => {\n        collection.conflicts.map((conflict) => {\n            if (! conflictDatesByMessage[conflict.message]) {\n                Object.assign({}, conflictDatesByMessage[conflict.message] = []);\n            }\n            conflictDatesByMessage[conflict.message].push(formatDate(collection.date))\n        })\n    })\n\n    return (\n        Object.keys(conflictDatesByMessage).map((key, index) => {\n            return (\n                <div key={index}>\n                    <div><strong>{ conflictDatesByMessage[key].join(\", \")  }</strong></div>\n                    <div key={index}>- {key}</div>\n                </div>\n            )\n        })\n    )\n    \n    \n}\n\nconst Conflicts = (props) => {\n    const conflicts = Object.keys(props.conflictList).map(key => {\n        return {\n            date: key,\n            conflicts: props.conflictList[key]\n        }\n    })\n    return (\n        conflicts.length ? \n        <div className=\"message message--error\" role=\"alert\" aria-live=\"polite\">\n            <h3>Folgende Zeiten führen mit der aktuellen Auswahl zu Konflikten:</h3>\n            {renderConflictList(conflicts)}\n        </div> : null\n    )\n}\n\nConflicts.defaultProps = {\n    conflictList: {}\n}\n\nConflicts.propTypes = {\n    conflictList: PropTypes.object\n}\n\nexport default Conflicts\n","import React from 'react'\nimport PropTypes from 'prop-types' \nimport Errors from './form/errors'\nimport Conflicts from './form/conflicts'\n \nconst ErrorBar = (props) => {\n    const { errorList, conflictList } = props\n    return (\n        <div ref={props.setErrorRef} id=\"errorRef\">\n            <Errors {...{ errorList }} />\n            <Conflicts {...{ conflictList }} />\n       </div>\n    )\n}\n\nErrorBar.propTypes = {\n    setErrorRef: PropTypes.func,\n    errorList: PropTypes.object,\n    conflictList: PropTypes.object\n}\n\nexport default ErrorBar\n","import React from 'react'\nimport PropTypes from 'prop-types'\nimport * as Inputs from '../../../lib/inputs'\nimport AvailabilityDatePicker from './datepicker'\nconst { Label, FormGroup, Controls, Description } = Inputs\nimport { range } from '../../../lib/utils'\nimport { weekDayList, availabilitySeries, availabilityTypes, getDataValuesFromForm } from '../helpers'\nimport ErrorBar from '../errorBar'\n\nconst FormContent = (props) => {\n    const {\n        availabilityList, \n        data, \n        errorList, \n        conflictList,\n        onChange, \n        today, \n        setErrorRef\n    } = props;\n    \n    const calenderDisabled = data.type && data.slotTimeInMinutes ? false : true\n    return (\n        <div>\n            <ErrorBar errorList={errorList} conflictList={conflictList} setErrorRef={setErrorRef} />\n            <form className=\"form--base\">\n                <fieldset>\n                    <div className=\"panel--heavy\">\n                        <FormGroup>\n                            <Label attributes={{\"htmlFor\": \"AvDayDescription\"}}>Anmerkung</Label> \n                            <Controls>\n                                <Inputs.Text \n                                    attributes={{ \"id\": \"AvDayDescription\", \"aria-describedby\": \"help_AvDayDescription\" }}\n                                    name=\"description\" \n                                    value={data.description} \n                                    {...{ onChange }} \n                                />\n                                <Description attributes={{ \"id\": \"help_AvDayDescription\" }} value=\"Optionale Angabe zur Kennzeichnung des Termins.\">\n                                    {data.id ? \" Die ID der Öffnungszeit ist \" + data.id : \" Die Öffnungszeit hat noch keine ID\"}\n                                </Description>\n                            </Controls>\n                        </FormGroup>\n                        <FormGroup>\n                            <Label attributes={{\"htmlFor\": \"AvDayType\"}}>Typ</Label>\n                            <Controls>\n                                <Inputs.Select name=\"type\"\n                                    attributes={{ disabled: data.id ? 'disabled' : null, \"id\": \"AvDayType\" }}\n                                    value={data.type ? data.type : 0} {...{ onChange }}\n                                    options={availabilityTypes} />\n                            </Controls>\n                        </FormGroup>\n                    </div>\n                </fieldset>\n                <fieldset>\n                    <div className=\"panel--heavy\">\n                        <legend className=\"label\">Serie und Wochentage</legend>\n                        <FormGroup>\n                            <Label attributes={{\"htmlFor\": \"AvDaySeries\", \"className\": \"light\"}}>Serie</Label>\n                            <Controls>\n                                <Inputs.Select \n                                    name=\"repeat\"\n                                    attributes={{ \"id\": \"AvDaySeries\" }} \n                                    value={data.repeat} {...{ onChange }}\n                                    options={availabilitySeries} />\n                            </Controls>\n                        </FormGroup>\n                        <FormGroup>\n                            <Label attributes={{\"className\": \"light\"}}>Wochentage</Label>\n                            <Controls>\n                                <Inputs.CheckboxGroup name=\"weekday\"\n                                    value={data.weekday}\n                                    inline={true}\n                                    {...{ onChange }}\n                                    boxes={weekDayList}\n                                    disabled={!data.repeat ? true : false}\n                                />\n                            </Controls>\n                        </FormGroup>\n                    </div>\n                </fieldset>\n                <fieldset>\n                    <div className=\"panel--heavy\">\n                        <legend className=\"label\">Terminabstand</legend>\n                        <FormGroup inline={true}>    \n                            <Controls>\n                                <Inputs.Text name=\"slotTimeInMinutes\"\n                                    value={data.slotTimeInMinutes}\n                                    width=\"2\"\n                                    attributes={{ disabled: 'disabled', maxLength: 3, \"id\": \"AvDaySlottime\" }}\n                                    {...{ onChange }} />\n                                <Label attributes={{\"htmlFor\": \"AvDaySlottime\", \"className\": \"light\"}}>&nbsp;Minuten Abstand zweier aufeinander folgender Termine</Label>\n                            </Controls>\n                        </FormGroup>\n                        <FormGroup inline={true}>    \n                            <Controls>\n                                <Inputs.Checkbox name=\"multipleSlotsAllowed\"\n                                    checked={\"1\" == data.multipleSlotsAllowed} {...{ onChange }} \n                                    value=\"1\"\n                                    attributes={{ \"id\": \"AvDayMultipleSlots\" }}\n                                />\n                                <Label attributes={{\"htmlFor\": \"AvDayMultipleSlots\", \"className\": \"light\"}}>Die Dienstleistungen dürfen mehr als einen Zeitschlitz beanspruchen</Label>\n                            </Controls>\n                        </FormGroup>\n                    </div>\n                </fieldset>\n                \n                <fieldset>\n                    <div className=\"panel--heavy\">\n                        <legend className=\"label\">Öffnungszeit</legend>\n                        <AvailabilityDatePicker attributes={{\n                            \"id\": \"AvDatesStart\", \n                            \"availabilitylist\": availabilityList,\n                            \"availability\": getDataValuesFromForm(data, data.scope),\n                            \"today\": today,\n                            \"disabled\": calenderDisabled\n                        }} name=\"startDate\" {...{ onChange }} />\n                        <AvailabilityDatePicker attributes={{\n                            \"id\": \"AvDatesEnd\", \n                            \"availabilitylist\": availabilityList,\n                            \"availability\": getDataValuesFromForm(data, data.scope),\n                            \"today\": today,\n                            \"disabled\": calenderDisabled\n                        }} name=\"endDate\" {...{ onChange }} />\n                    </div>\n                </fieldset>\n\n                <fieldset>\n                    <div className=\"panel--heavy\">\n                        <legend className=\"label\">Buchbar</legend>\n                        <FormGroup inline={true}>\n                            <Controls>\n                                <Label attributes={{\"htmlFor\": \"AvDayOpenfrom\", \"className\": \"light\"}}>von</Label> \n                                <Inputs.Text name=\"open_from\"\n                                    width=\"2\"\n                                    value={data.open_from}\n                                    attributes={{ placeholder: data.scope.preferences.appointment.startInDaysDefault, \"id\": \"AvDayOpenfrom\", \"aria-describedby\": \"help_AvDayOpenfromto\" }}\n                                    {...{ onChange }}\n                                />\n                            </Controls>\n                            <Controls>\n                                <Label attributes={{\"htmlFor\": \"AvDayOpento\", \"className\": \"light\"}}>bis</Label> \n                                    <Inputs.Text name=\"open_to\"\n                                    width=\"2\"\n                                    value={data.open_to}\n                                    attributes={{ placeholder: data.scope.preferences.appointment.endInDaysDefault, \"id\": \"AvDayOpento\", \"aria-describedby\": \"help_AvDayOpenfromto\" }}\n                                    {...{ onChange }}\n                                />\n                                <span aria-hidden=\"true\"> Tage im voraus</span>\n                            </Controls>\n                            <Description attributes={{ \"id\": \"help_AvDayOpenfromto\" }}>Tage im voraus (Keine Eingabe bedeutet die Einstellungen vom Standort zu übernehmen).</Description>\n                        </FormGroup>\n                    </div>\n                </fieldset>\n\n                <fieldset>\n                    <div className=\"panel--heavy\">\n                        {data.type !== 'openinghours' ? <legend>Terminarbeitsplätze</legend> : null}\n                        {data.type !== 'openinghours' ?\n                            <div>\n                                <FormGroup>\n                                    <Label attributes={{\"htmlFor\": \"WsCountIntern\"}}>Insgesamt</Label>\n                                    <Controls>\n                                        <Inputs.Select name=\"workstationCount_intern\"\n                                            value={data.workstationCount_intern}\n                                            attributes={{\"id\": \"WsCountIntern\"}}\n                                            {...{ onChange }}\n                                            options={range(0, 50).map(n => {\n                                                let workstation = (n == 1) ? \"Arbeitsplatz\" : \"Arbeitsplätze\";\n                                                return {\n                                                    title: `${n} ${workstation}`,\n                                                    value: `${n}`,\n                                                    name: `${n} ${workstation}`\n                                                }\n                                            })} />\n                                    </Controls>\n                                </FormGroup>\n\n                                <FormGroup>\n                                    <Label attributes={{\"htmlFor\": \"WsCountCallcenter\"}}>Callcenter</Label>\n                                    <Controls>\n                                        <Inputs.Select name=\"workstationCount_callcenter\"\n                                            value={data.workstationCount_callcenter}\n                                            attributes={{\"id\": \"WsCountCallcenter\", \"aria-describedby\": \"help_WsCountCallcenter\"}}\n                                            {...{ onChange }}\n                                            options={range(0, data.workstationCount_intern).map(n => {\n                                                let workstation = (n == 1) ? \"Arbeitsplatz\" : \"Arbeitsplätze\";\n                                                return {\n                                                    title: `${n} ${workstation}`,\n                                                    value: `${n}`,\n                                                    name: `${n} ${workstation}`\n                                                }\n                                            })} />\n                                        <Description attributes={{\"id\": \"help_WsCountCallcenter\"}}>Wieviele der insgesamt verfügbaren Terminarbeitsplätze sollen für das Callcenter zur Verfügung gestellt werden.</Description>\n                                    </Controls>\n                                </FormGroup>\n\n                                <FormGroup>\n                                    <Label attributes={{\"htmlFor\": \"WsCountPublic\"}}>Internet</Label>\n                                    <Controls>\n                                        <Inputs.Select name=\"workstationCount_public\"\n                                            value={data.workstationCount_public}\n                                            attributes={{\"id\": \"WsCountPublic\", \"aria-describedby\": \"help_WsCountPublic\"}}\n                                            {...{ onChange }}\n                                            options={range(0, data.workstationCount_intern).map(n => {\n                                                let workstation = (n == 1) ? \"Arbeitsplatz\" : \"Arbeitsplätze\";\n                                                return {\n                                                    title: `${n} ${workstation}`,\n                                                    value: `${n}`,\n                                                    name: `${n} ${workstation}`\n                                                }\n                                            })} />\n                                        <Description attributes={{\"htmlFor\": \"help_WsCountPublic\"}}>Wieviele der insgesamt verfügbaren Terminarbeitsplätze sollen für das Internet zur Verfügung gestellt werden.</Description>\n                                    </Controls>\n                                </FormGroup>\n                            </div>\n                            : null}\n                        </div>\n                    </fieldset>\n            </form>\n        </div>\n    )\n}\n\nFormContent.propTypes = {\n    availabilityList: PropTypes.array,\n    errorList: PropTypes.object,\n    conflictList: PropTypes.object,\n    today: PropTypes.number,\n    data: PropTypes.object,\n    errors: PropTypes.object,\n    onChange: PropTypes.func,\n    setErrorRef: PropTypes.func,\n}\n\nexport default FormContent \n","import React, { Component } from 'react'\nimport PropTypes from 'prop-types'\nimport FormButtons from './formButtons'\nimport FormContent from './content'\nimport { getDataValuesFromForm, cleanupFormData, getFormValuesFromData } from '../helpers'\n\nclass AvailabilityForm extends Component {\n    constructor(props) {\n        super(props);\n        this.state = {\n            data: getFormValuesFromData(this.props.data)\n        };\n    }\n\n    componentDidUpdate(prevProps) {\n        if (this.props.data && this.props.data !== prevProps.data) {\n            this.setState({\n                data: getFormValuesFromData(this.props.data)\n            })\n        }\n    }\n\n    handleChange(name, value) {\n        this.setState((state) => ({\n            data: cleanupFormData(Object.assign({}, state.data, {\n                [name]: value,\n                __modified: true\n            }))\n        }), () => {\n            this.props.handleChange(getDataValuesFromForm(this.state.data, this.props.data.scope))\n        })\n    }\n\n    render() {\n        const { data } = this.state\n        const onChange = (name, value) => {\n            this.handleChange(name, value)\n        }\n\n        return (\n            <div>\n                {<FormContent \n                    today = {this.props.today} \n                    availabilityList={this.props.availabilityList}\n                    setErrorRef={this.props.setErrorRef}\n                    errorList={this.props.errorList}\n                    conflictList={this.props.conflictList}\n                    {... { data, onChange }} />}\n                {<FormButtons \n                    data = {data}\n                    onCopy={this.props.onCopy} \n                    onExclusion={this.props.onExclusion}\n                    onEditInFuture={this.props.onEditInFuture} \n                    onDelete={this.props.onDelete}\n                    selectedDate={this.props.selectedDate}\n                />}\n            </div>\n        )   \n    }\n}\n\nAvailabilityForm.defaultProps = {\n    data: {},\n    handleChange: () => { },\n    onCopy: () => { },\n    onExclusion: () => { },\n    onEditInFuture: () => { }\n}\n\nAvailabilityForm.propTypes = {\n    availabilityList: PropTypes.array,\n    errorList: PropTypes.object,\n    conflictList: PropTypes.object,\n    data: PropTypes.object,\n    today: PropTypes.number,\n    selectedDate: PropTypes.number,\n    handleChange: PropTypes.func,\n    onCopy: PropTypes.func,\n    onExclusion: PropTypes.func,\n    onEditInFuture: PropTypes.func,\n    setErrorRef: PropTypes.func,\n    onDelete: PropTypes.func\n}\n\nexport default AvailabilityForm\n","import React from 'react'\nimport PropTypes from 'prop-types'\n\nconst FooterButtons = (props) => {\n    const { hasConflicts, stateChanged, data, onNew, onPublish, onAbort } = props\n    return (\n        <div className=\"form-actions\" style={{\"marginTop\":\"0\", \"padding\":\"0.75em\"}}>    \n                 <button title=\"Neue Öffnungszeit anlegen und bearbeiten\" className=\"button button--diamond button-new\" onClick={onNew} disabled={(stateChanged || hasConflicts || data)}>neue Öffnungszeit</button> \n                <button title=\"Alle Änderungen werden zurückgesetzt\" className=\"button btn\" type=\"abort\" onClick={onAbort} disabled={(!stateChanged && !hasConflicts && !data)}>Abbrechen</button>\n                <button title=\"Alle Änderungen werden gespeichert\" className=\"button button--positive button-save\" type=\"save\" value=\"publish\" onClick={onPublish} disabled={(! stateChanged || hasConflicts)}>Alle Änderungen aktivieren\n                </button>\n             \n        </div>\n       \n    )\n}\n\nFooterButtons.propTypes = {\n    data: PropTypes.object,\n    hasConflicts: PropTypes.bool,\n    stateChanged: PropTypes.bool,\n    onNew: PropTypes.func,\n    onPublish: PropTypes.func,\n    onAbort: PropTypes.func\n}\n\nexport default FooterButtons\n","import React, { Component} from 'react'\nimport PropTypes from 'prop-types'\nimport moment from 'moment/min/moment-with-locales';\nimport AvailabilityForm from '../form'\nimport FooterButtons from '../form/footerButtons'\nimport {accordionTitle} from '../helpers'\nimport Board from './board'\nmoment.locale('de')\n\nclass Accordion extends Component \n{\n    constructor(props) {\n        super(props);\n        this.isExpanded = null\n    } \n\n    componentDidUpdate(prevProps) {\n        var eventId = null\n        if (prevProps.data !== this.props.data) {\n            if (this.props.data) {\n                eventId = (this.props.data.id) ? this.props.data.id : this.props.data.tempId;\n            }\n            this.isExpanded = eventId\n        }\n    }\n    \n    render() {\n        const onPublish = (ev) => {\n            ev.preventDefault()\n            this.props.onPublish()\n        }\n\n        const onAbort = (ev) => {\n            ev.preventDefault()\n            this.props.onAbort()\n        }\n\n        const onNew = (ev) => {\n            ev.preventDefault()\n            this.props.onNew()\n        }\n\n        const hasConflict = (eventId) => {\n            return (\n                Object.keys(this.props.conflictList.itemList).length > 0 && \n                this.props.conflictList.conflictIdList.includes(eventId) \n            )\n        }\n\n        const hasError = (eventId) => {\n            return (\n                Object.keys(this.props.errorList).length > 0 && \n                Object.values(this.props.errorList).find(item => item.id == eventId)\n            )\n        }\n        \n        const renderAccordionBody = () => {\n            return this.props.availabilities.map((availability, index) => {\n                if (! availability.id && ! availability.tempId) {\n                    availability.tempId = `spontaneous_ID_${index}`\n                }\n                let eventId = availability.id ? availability.id : availability.tempId;\n            \n                const onToggle = ev => {\n                    ev.preventDefault();\n                    if (eventId == ev.currentTarget.attributes.eventkey.value && eventId != this.isExpanded) {\n                        this.isExpanded = eventId\n                        this.props.onSelect(availability)\n                    } else {\n                        this.isExpanded = null\n                        this.props.onSelect(null)\n                    }\n                }\n\n                const onCopy = ev => {\n                    ev.preventDefault()\n                    this.props.onCopy(availability)\n                }\n\n                const onExclusion = ev => {\n                    ev.preventDefault()\n                    this.props.onExclusion(availability)\n                }\n\n                const onEditInFuture = ev => {\n                    ev.preventDefault()\n                    this.props.onEditInFuture(availability)\n                }\n\n                const onDelete = ev => {\n                    ev.preventDefault()\n                    this.props.onDelete(availability)\n                }\n        \n                let title = accordionTitle(availability);\n\n                let conflictList = []\n                Object.keys(this.props.conflictList.itemList).map(date => {\n                    (this.props.conflictList.itemList[date].map(conflict => {\n                        if (conflict.appointments[0].availability == eventId) {\n                            if (! conflictList[date]) {\n                                conflictList[date] = [];\n                            }\n                            conflictList[date].push(conflict); \n                        }\n                    }))\n                })\n                return (\n                    <section key={index} className=\"accordion-section\" style={hasConflict(eventId) || hasError(eventId) ? { border: \"1px solid #9B0000\"} : null}>\n                        <h3 className=\"accordion__heading\" role=\"heading\" title={title}>\n                            <button eventkey={eventId} onClick={onToggle} className=\"accordion__trigger\" aria-expanded={eventId == this.isExpanded}>\n                                <span className=\"accordion__title\">{title}</span>\n                            </button>\n                        </h3>\n                        <div className={eventId == this.isExpanded ? \"accordion__panel opened\" : \"accordion__panel\"} hidden={eventId == this.isExpanded ? \"\" : \"hidden\"}>\n                            <AvailabilityForm \n                                data={availability}\n                                selectedAvailability={this.props.data}\n                                availabilityList={this.props.availabilities}\n                                today={this.props.today}\n                                selectedDate={moment(this.props.timestamp, 'X').startOf('day').unix()}\n                                handleChange={this.props.handleChange}\n                                setErrorRef={this.props.setErrorRef}\n                                onCopy={onCopy}\n                                onExclusion={onExclusion}\n                                onEditInFuture={onEditInFuture}\n                                onDelete={onDelete}\n                                errorList={hasError(eventId) ? this.props.errorList : {}}\n                                conflictList={hasConflict(eventId) ? Object.assign({}, conflictList): {}}\n                            />\n                        </div>\n                    </section>\n                )\n            })\n        }\n        return (\n            <Board className=\"accordion js-accordion\"\n                title=\"\"\n                body={renderAccordionBody()}\n                footer={<FooterButtons \n                    hasConflicts={Object.keys(this.props.conflictList.itemList).length || Object.keys(this.props.errorList).length ? true : false}\n                    stateChanged={this.props.stateChanged} \n                    data={this.props.data} \n                    {...{onNew, onPublish, onAbort }} \n                />}\n            />\n        )\n    }\n}\n\nAccordion.propTypes = {\n    data: PropTypes.object,\n    availabilities: PropTypes.array,\n    errorList: PropTypes.object,\n    conflictList: PropTypes.object,\n    today: PropTypes.number,\n    timestamp: PropTypes.number,\n    onSelect: PropTypes.func,\n    handleChange: PropTypes.func,\n    onPublish: PropTypes.func,\n    onDelete: PropTypes.func,\n    onAbort: PropTypes.func,\n    onNew: PropTypes.func,\n    onCopy: PropTypes.func,\n    onExclusion: PropTypes.func,\n    onEditInFuture: PropTypes.func,\n    setErrorRef: PropTypes.func,\n    stateChanged: PropTypes.bool,\n    errorElement: PropTypes.element\n}\n\nexport default Accordion\n","import React from 'react'\nimport PropTypes from 'prop-types'\n\n\n\nconst PageLayout = (props) => {\n    return (\n        <div>\n            {props.conflicts}\n            {props.tabs}\n            {props.timeTable}\n            {props.saveBar}\n            {props.accordion}\n        </div>\n    )\n}\n\nPageLayout.propTypes = {\n    timeTable: PropTypes.node,\n    accordion: PropTypes.node,\n    conflicts: PropTypes.node,\n    tabs: PropTypes.node,\n    saveBar: PropTypes.node\n}\n\nexport default PageLayout\n","import React, { Component } from 'react'\nimport PropTypes from 'prop-types'\nimport $ from 'jquery'\nimport moment from 'moment'\nimport validate from './form/validate'\nimport Conflicts from './conflicts'\nimport TabsBar from './tabsbar'\nimport GraphView from './timetable/graphview.js'\nimport TableView from './timetable/tableview.js'\nimport SaveBar from './saveBar'\nimport AccordionLayout from './layouts/accordion'\nimport PageLayout from './layouts/page'\nimport { inArray, showSpinner, hideSpinner } from '../../lib/utils'\n\nimport {\n    getInitialState,\n    getStateFromProps,\n    getNewAvailability,\n    mergeAvailabilityListIntoState,\n    updateAvailabilityInState,\n    cleanupAvailabilityForSave,\n    deleteAvailabilityInState,\n    findAvailabilityInStateByKind,\n    formatTimestampDate\n} from \"./helpers\"\n\nconst tempId = (() => {\n    let lastId = -1\n\n    return () => {\n        lastId += 1\n        return `__temp__${lastId}`\n    }\n})()\n\nclass AvailabilityPage extends Component {\n    constructor(props) {\n        super(props)\n        this.state = getInitialState(props)\n        this.waitintervall = 1000;\n        this.errorElement = null;\n        this.successElement = null;\n        this.setErrorRef = element => {\n            this.errorElement = element\n        };\n        this.setSuccessRef = element => {\n            this.successElement = element\n        };\n    }\n\n    componentDidMount() {\n        this.unloadHandler = ev => {\n            const confirmMessage = \"Es wurden nicht alle Änderungen gespeichert. Diese gehen beim schließen verloren.\"\n            if (this.state.stateChanged) {\n                ev.returnValue = confirmMessage\n                return confirmMessage\n            }\n        }\n\n        window.addEventListener('beforeunload', this.unloadHandler)\n    }\n\n    componentDidUnMount() {\n        window.removeEventListener('beforeunload', this.unloadHandler)\n    }\n\n    /* not in use anymore\n    onUpdateAvailability(availability) {\n        let state = {};\n        if (availability.__modified || this.state.stateChanged) {\n            state = Object.assign(state, updateAvailabilityInState(this.state, availability), {\n                selectedAvailability: null\n            })\n        } else {\n            state = { selectedAvailability: null }\n        }\n        this.setState(state);\n        $('body').scrollTop(0);\n        return state;\n    }\n    */\n\n    onPublishAvailability() {\n        let state = {};\n        state = { selectedAvailability: null }\n        this.setState(state, () => {\n            this.onSaveUpdates();\n        });\n    }\n\n    refreshData() {\n        const currentDate = formatTimestampDate(this.props.timestamp)\n        const url = `${this.props.links.includeurl}/scope/${this.props.scope.id}/availability/day/${currentDate}/conflicts/`\n        $.ajax(url, {\n            method: 'GET'\n        }).done(data => {\n            const newProps = {\n                conflicts: data.conflicts,\n                availabilitylist: data.availabilityList,\n                availabilitylistslices: data.availabilityListSlices,\n                busyslots: data.busySlotsForAvailabilities,\n                maxslots: data.maxSlotsForAvailabilities\n            }\n            this.setState(Object.assign({}, getStateFromProps(Object.assign({}, this.props, newProps)), {\n                stateChanged: false,\n                selectedAvailability: null\n            }))\n\n        }).fail(err => {\n            console.log('refreshData error', err)\n        })\n    }\n\n    onSaveUpdates() {\n        showSpinner();\n        const sendData = this.state.availabilitylist.map(availability => {\n            const sendAvailability = Object.assign({}, availability)\n            if (availability.tempId) {\n                delete sendAvailability.tempId\n            }\n            return sendAvailability\n        }).map(cleanupAvailabilityForSave)\n            \n        console.log('Saving updates', sendData)\n\n        $.ajax(`${this.props.links.includeurl}/availability/`, {\n            method: 'POST',\n            data: JSON.stringify(sendData)\n        }).done((success) => {\n            console.log('save success', success)\n            this.refreshData()\n            this.setState({\n                lastSave: new Date().getTime(),\n            }, () => {\n                this.successElement.scrollIntoView();\n            })\n            hideSpinner();\n        }).fail((err) => {\n            if (err.status === 404) {\n                console.log('404 error, ignored')\n                this.refreshData()\n            } else {\n                console.log('save error', err)\n            }\n            hideSpinner();\n        })\n    }\n\n\n    onRevertUpdates() {\n        this.setState(Object.assign({}, getInitialState(this.props), {\n            selectedTab: this.state.selectedTab\n        }), () => {\n            this.refreshData()\n            this.getConflictList(),\n            this.getValidationList()\n        })\n    }\n\n    onDeleteAvailability(availability) {\n        console.log('Deleting', availability)\n        showSpinner();\n        const ok = confirm('Soll diese Öffnungszeit wirklich gelöscht werden?')\n        const id = availability.id\n        if (ok) {\n            $.ajax(`${this.props.links.includeurl}/availability/delete/${id}/`, {\n                method: 'GET'\n            }).done(() => {\n                this.setState(Object.assign({}, deleteAvailabilityInState(this.state, availability), {\n                    selectedAvailability: null\n                }), () => {\n                    this.refreshData()\n                    this.getConflictList(),\n                    this.getValidationList()\n                });\n                hideSpinner();\n            }).fail(err => {\n                console.log('delete error', err);\n                hideSpinner();\n            })\n        }\n    }\n\n    onCopyAvailability(availability) {\n        const start = formatTimestampDate(availability.startDate)\n        const end = formatTimestampDate(availability.endDate)\n\n        let copysourcetitle = (availability.description) ? availability.description : `${start} - ${end}`;\n        const copyAvailability = Object.assign({}, availability, {\n            tempId: tempId(),\n            id: null,\n            description: `Kopie von ${copysourcetitle}`\n        })\n        this.setState(Object.assign(\n            {},\n            mergeAvailabilityListIntoState(this.state, [copyAvailability]),\n            { selectedAvailability: copyAvailability, stateChanged: true }\n        ), () => {\n            this.getConflictList(),\n            this.getValidationList()\n        })\n    }\n\n    onSelectAvailability(availability) {\n        this.setState({\n            selectedAvailability: availability\n        }, () => {\n            this.getConflictList()\n            this.getValidationList()\n        })\n    }\n\n    editExclusionAvailability(availability, startDate, endDate, description, kind) {\n        (startDate) ? availability.startDate = startDate : null;\n        (endDate) ? availability.endDate = endDate : null;\n        if (! availability.kind && kind != 'origin') {\n            availability.tempId = tempId()\n            availability.id = null\n            availability.description = (description) ? description : availability.description\n            availability.kind = kind\n        } else {\n            availability.kind = 'origin'\n        }\n        return availability;\n    }\n\n    onCreateExclusionForAvailability(availability) {\n        const selectedDay = moment(this.props.timestamp, 'X').startOf('day')\n        const yesterday = selectedDay.clone().subtract(1, 'days')\n        const tomorrow = selectedDay.clone().add(1, 'days')\n\n        let endDateTimestamp = (parseInt(yesterday.unix(), 10) < availability.startDate) ? \n            parseInt(selectedDay.unix(), 10) : \n            parseInt(yesterday.unix(), 10);\n\n        const originAvailability = this.editExclusionAvailability(\n            Object.assign({}, availability),\n            null, \n            endDateTimestamp,\n            null,\n            'origin'\n        )\n\n        let exclusionAvailability = originAvailability;\n        if (originAvailability.startDate < selectedDay.unix()) {\n            exclusionAvailability = this.editExclusionAvailability(\n                Object.assign({}, availability),\n                parseInt(selectedDay.unix(), 10), \n                parseInt(selectedDay.unix(), 10),\n                `Ausnahme ${formatTimestampDate(selectedDay)} (${availability.id})`,\n                'exclusion'\n            )\n        }\n        \n\n        let futureAvailability = originAvailability;\n        if (parseInt(tomorrow.unix(), 10) < availability.endDate) {\n            futureAvailability = this.editExclusionAvailability(\n                Object.assign({}, availability),\n                parseInt(tomorrow.unix(), 10),\n                null,\n                `Fortführung der Ausnahme ${formatTimestampDate(selectedDay)} (${availability.id})`,\n                'future'\n            )\n        }\n\n        this.setState(Object.assign({},\n            mergeAvailabilityListIntoState(this.state, [\n                originAvailability,\n                exclusionAvailability,\n                futureAvailability\n            ]),\n            { \n                selectedAvailability: exclusionAvailability, \n                stateChanged: true \n            }\n        ), () => {\n            this.getConflictList(),\n            this.getValidationList()\n        })\n    }\n\n    onEditAvailabilityInFuture(availability) {\n        const selectedDay = moment(this.props.timestamp, 'X').startOf('day')\n        const yesterday = selectedDay.clone().subtract(1, 'days')\n        let endDateTimestamp = (parseInt(yesterday.unix(), 10) < availability.startDate) ? \n            parseInt(selectedDay.unix(), 10) : \n            parseInt(yesterday.unix(), 10);\n\n        const originAvailability = this.editExclusionAvailability(\n            Object.assign({}, availability),\n            null, \n            endDateTimestamp,\n            null,\n            'origin'\n        )\n\n        let futureAvailability = originAvailability;\n        if (parseInt(selectedDay.unix(), 10) <= availability.endDate) {\n            futureAvailability = this.editExclusionAvailability(\n                Object.assign({}, availability),\n                parseInt(selectedDay.unix(), 10),\n                null,\n                `Änderung ab ${formatTimestampDate(selectedDay)} (${availability.id})`,\n                'future'\n            )\n        }\n\n        this.setState(Object.assign({},\n            mergeAvailabilityListIntoState(this.state, [\n                originAvailability,\n                futureAvailability\n            ]),\n            { \n                selectedAvailability: futureAvailability, \n                stateChanged: true \n            }\n        ), () => {\n            this.getConflictList(),\n            this.getValidationList()\n        })\n    }\n\n    onNewAvailability() {\n        let state = {};\n        const newAvailability = getNewAvailability(this.props.timestamp, tempId(), this.props.scope)\n        state = Object.assign(\n            state, \n            updateAvailabilityInState(this.state, newAvailability), \n            { selectedAvailability: newAvailability, stateChanged: false }\n        );\n        this.setState(state, () => {\n            this.getConflictList()\n        });\n        $('body').scrollTop(0);\n    }\n\n    onTabSelect(tab) {\n        this.setState({ selectedTab: tab.component });\n    }\n\n    onConflictedIdSelect(id) {\n        const availability = this.state.availabilitylist.filter(availability => availability.id === id)[0]\n        if (availability) {\n            this.setState({ selectedAvailability: availability })\n        }\n    }\n\n    getValidationList(list = []) {\n        const validateData = data => {\n            let validationResult = validate(data, this.props)\n            if (!validationResult.valid) {\n                return validationResult.errorList              \n                \n            } \n            return [];\n        }\n\n        this.state.availabilitylist.map(availability => {\n            list.push(validateData(availability))\n        })\n        list = list.filter(el => el.id)\n\n        this.setState({\n            errorList: list.length ? Object.assign({}, list) : {}\n        }, () => {\n            if (list.length) {\n                this.errorElement.scrollIntoView()\n            }\n        })\n    }\n\n    getConflictList() {\n        const requestOptions = {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify(Object.assign({}, {\n                availabilityList: this.state.availabilitylist, \n                selectedDate: formatTimestampDate(this.props.timestamp),\n                selectedAvailability: this.state.selectedAvailability\n            }))\n        };\n        const url = `${this.props.links.includeurl}/availability/conflicts/`;\n        fetch(url, requestOptions)\n            .then(res => res.json())\n            .then(\n                (data) => {\n                    this.setState({\n                        conflictList: Object.assign({}, \n                            {\n                                itemList: Object.assign({}, data.conflictList), \n                                conflictIdList: data.conflictIdList\n                            }\n                        )\n                    })\n                    if (data.conflictIdList.length > 0) {\n                        this.errorElement.scrollIntoView()\n                    }\n                },\n                (error) => {\n                    console.log(error)\n                }\n            )\n    }\n\n    renderTimeTable() {\n        const onSelect = data => {\n            this.onSelectAvailability(data)\n        }\n\n        const onDelete = data => {\n            this.onDeleteAvailability(data)\n        }\n\n        const ViewComponent = this.state.selectedTab == 'graph' ? GraphView : TableView;\n        return <ViewComponent\n            timestamp={this.props.timestamp}\n            conflicts={this.state.conflicts}\n            availabilities={this.state.availabilitylist}\n            data={this.state.selectedAvailability}\n            availabilityListSlices={this.state.availabilitylistslices}\n            maxWorkstationCount={this.props.maxworkstationcount}\n            links={this.props.links}\n            onSelect={onSelect}\n            onDelete={onDelete}\n            onAbort={this.onRevertUpdates.bind(this)}\n        />\n    }\n\n    handleChange(data) {\n        if (data.__modified) {\n            clearTimeout(this.timer)\n            this.setState(\n                Object.assign({}, updateAvailabilityInState(this.state, data), {selectedAvailability: data}),\n                () => {\n                    if (data.tempId || data.id) {\n                        this.timer = setTimeout(() => {\n                            this.getConflictList()\n                            this.getValidationList()\n                        }, this.waitintervall)\n                    }\n                }\n            );\n        }\n        if (data.kind && inArray(data.kind, [\"origin\", \"future\", \"exclusion\"])) {\n            this.handleChangesAvailabilityExclusion(data)\n        }\n    }\n\n    handleChangesAvailabilityExclusion(data) {\n        if ('origin' == data.kind && data.__modified) {\n            this.handleOriginChanges(data)\n        }\n        if ('exclusion' == data.kind && data.__modified) {\n            this.handleExclusionChanges(data)        \n        }\n        if ('future' == data.kind && data.__modified) {\n            this.handleFutureChanges(data)\n        }\n    }\n\n    handleOriginChanges(data) {\n        const exclusionAvailabilityFromState = findAvailabilityInStateByKind(this.state, 'exclusion');\n        const futureAvailabilityFromState = findAvailabilityInStateByKind(this.state, 'future');\n        \n        const exclusionAvailability = (exclusionAvailabilityFromState) ? Object.assign({}, exclusionAvailabilityFromState, {\n            startDate: moment(data.endDate, 'X').startOf('day').add(1, 'days').unix(),\n            endDate: (exclusionAvailabilityFromState.endDate > moment(data.endDate, 'X').startOf('day').add(1, 'days').unix()) ?\n                exclusionAvailabilityFromState.endDate :\n                moment(data.endDate, 'X').startOf('day').add(1, 'days').unix()\n        }) : data;\n    \n        const futureAvailability = Object.assign({}, futureAvailabilityFromState, {\n            startDate: moment(exclusionAvailability.endDate, 'X').startOf('day').add(1, 'days').unix(),\n            endDate: (\n                futureAvailabilityFromState.endDate > moment(exclusionAvailability.endDate, 'X').startOf('day').add(1, 'days').unix()) ?\n                futureAvailabilityFromState.endDate :\n                moment(exclusionAvailability.endDate, 'X').startOf('day').add(1, 'days').unix()\n        });\n        this.setState(Object.assign(\n            {},\n            mergeAvailabilityListIntoState(this.state, [exclusionAvailability, futureAvailability, data])\n        ));          \n    }\n\n    handleExclusionChanges(data) {\n        const originAvailabilityFromState = findAvailabilityInStateByKind(this.state, 'origin');\n        const futureAvailabilityFromState = findAvailabilityInStateByKind(this.state, 'future');\n\n        const exclusionAvailability = Object.assign({}, data, {\n            endDate: (data.startDate > data.endDate) ? data.startDate : data.endDate\n        });\n\n        const originAvailability = Object.assign({}, originAvailabilityFromState, {\n            endDate: moment(exclusionAvailability.startDate, 'X').startOf('day').subtract(1, 'days').unix()\n        });\n    \n        const futureAvailability = Object.assign({}, futureAvailabilityFromState, {\n            startDate: moment(exclusionAvailability.endDate, 'X').startOf('day').add(1, 'days').unix(),\n            endDate: (\n                futureAvailabilityFromState.endDate > moment(data.endDate, 'X').startOf('day').add(1, 'days').unix()) ?\n                futureAvailabilityFromState.endDate :\n                moment(data.endDate, 'X').startOf('day').add(1, 'days').unix()\n        });\n\n        this.setState(Object.assign(\n            {},\n            mergeAvailabilityListIntoState(this.state, [\n                originAvailability, \n                futureAvailability, \n                exclusionAvailability\n            ])\n        ));  \n    }\n\n    handleFutureChanges(data) {\n        const startDate = moment(data.startDate, 'X').startOf('day').add(1, 'days').unix();\n        const originAvailabilityFromState = findAvailabilityInStateByKind(this.state, 'origin');\n        const exclusionAvailabilityFromState = findAvailabilityInStateByKind(this.state, 'exclusion');\n        \n        const exclusionAvailability = (exclusionAvailabilityFromState) ? Object.assign({}, exclusionAvailabilityFromState, {\n            startDate: (startDate < exclusionAvailabilityFromState.endDate) ? \n                parseInt(startDate, 10) : \n                exclusionAvailabilityFromState.endDate\n        }) : data;\n\n        const originAvailability = Object.assign({}, originAvailabilityFromState, {\n            endDate: moment(exclusionAvailability.startDate, 'X').startOf('day').subtract(1, 'days').unix()\n        });\n    \n        this.setState(Object.assign(\n            {},\n            mergeAvailabilityListIntoState(this.state, [originAvailability, exclusionAvailability, data])\n        ));          \n    }\n\n    renderAvailabilityAccordion() {\n        const onSelect = data => {\n            this.onSelectAvailability(data)\n        }\n        const onCopy = data => {\n            this.onCopyAvailability(data)\n        }\n\n        const onExclusion = data => {\n            this.onCreateExclusionForAvailability(data)\n        }\n\n        const onEditInFuture = data => {\n            this.onEditAvailabilityInFuture(data)\n        }\n\n        const onDelete = data => {\n            this.onDeleteAvailability(data)\n        }\n\n        const onNew = data => {\n            this.onNewAvailability(data)\n        }\n\n        const handleChange = (data) => {\n            this.handleChange(data)\n        }\n\n        return <AccordionLayout \n            availabilities={this.state.availabilitylist}\n            data={this.state.selectedAvailability}\n            today={this.state.today}\n            timestamp={this.props.timestamp}\n            title=\"\"\n            onSelect={onSelect}\n            onPublish={this.onPublishAvailability.bind(this)}\n            onDelete={onDelete}\n            onNew={onNew}\n            onAbort={this.onRevertUpdates.bind(this)}\n            onCopy={onCopy}\n            onExclusion={onExclusion}\n            onEditInFuture={onEditInFuture}\n            handleChange={handleChange}\n            stateChanged={this.state.stateChanged}\n            includeUrl={this.props.links.includeurl}\n            setErrorRef={this.setErrorRef}\n            errorList={this.state.errorList ? \n                this.state.errorList : {}\n            }\n            conflictList={this.state.conflictList ? \n                this.state.conflictList : \n                {itemList: {}, conflictIdList: {}}\n            }\n        />\n    }\n\n    renderSaveBar() {\n        if (this.state.lastSave) {\n            return <SaveBar lastSave={this.state.lastSave} setSuccessRef={this.setSuccessRef} />\n        }\n    }\n\n    render() {\n        return (\n            <PageLayout\n                tabs={<TabsBar selected={this.state.selectedTab} tabs={this.props.tabs} onSelect={this.onTabSelect.bind(this)} />}\n                timeTable={this.renderTimeTable()}\n                saveBar={this.renderSaveBar()}\n                accordion={this.renderAvailabilityAccordion()}\n                conflicts={<Conflicts conflicts={this.state.conflicts} onSelect={this.onConflictedIdSelect.bind(this)} />}\n            />\n        )\n    }\n}\n\nAvailabilityPage.propTypes = {\n    maxworkstationcount: PropTypes.number,\n    timestamp: PropTypes.number,\n    scope: PropTypes.object,\n    links: PropTypes.object,\n    tabs: PropTypes.array\n}\n\nexport default AvailabilityPage\n","\"use strict\";\nmodule.exports = require(\"@apidevtools/json-schema-ref-parser\");\n","module.exports = require('./lib/defaults');\n","{\n    \"type\": \"object\",\n    \"description\": \"Representation of an Apikey. It usually stores temporary api quota data while appointment scheduling in service app\",\n    \"example\": {\n        \"key\": \"wMdVa5Nu1seuCRSJxhKl2M3yw8zqaAilPH2Xc2IZs\",\n        \"apiclient\": {\n            \"accesslevel\": \"public\",\n            \"clientKey\": \"hDUWCqKHuVbV2Yj9Dgc8hYwfAgJs3aTM\"\n        },\n        \"captcha\": {\n            \"mime\": \"image\\/jpeg;base64\",\n            \"content\": \"R0lGODdhEAAQAMwAAPj7+FmhUYjNfGuxYYDJdYTIeanOpT+DOTuANXi\\/bGOrWj6CONzv2sPjv2CmV1unU4zPgISg6DJnJ3ImTh8Mtbs00aNP1CZSGy0YqLEn47RgXW8amasW7XWsmmvX2iuXiwAAAAAEAAQAAAFVyAgjmRpnihqGCkpDQPbGkNUOFk6DZqgHCNGg2T4QAQBoIiRSAwBE4VA4FACKgkB5NGReASFZEmxsQ0whPDi9BiACYQAInXhwOUtgCUQoORFCGt\\/g4QAIQA7\",\n            \"base64\": true\n        },\n        \"quota\": [\n            {\n                \"route\": \"\\/calendar\\/\",\n                \"period\": \"hour\",\n                \"requests\": 99,\n                \"ts\": 1459512840\n            }\n        ],\n        \"createIP\": \"127.0.0.1\",\n        \"ts\": 1459512840\n    },\n    \"required\": [\n        \"key\"\n    ],\n    \"additionalProperties\": false,\n    \"properties\": {\n        \"key\": {\n            \"type\": \"string\",\n            \"description\": \"temporary random api key string\"\n        },\n        \"apiclient\": {\n            \"type\": \"object\",\n            \"description\": \"An apiclient is required on requesting an apikey.\",\n            \"example\": {\n                \"clientKey\": \"wMdVa5Nu1seuCRSJxhKl2M3yw8zqaAilPH2Xc2IZs\",\n                \"shortname\": \"example\",\n                \"accesslevel\": \"public\",\n                \"lastChange\": 1459512840\n            },\n            \"required\": [\n                \"clientKey\"\n            ],\n            \"additionalProperties\": false,\n            \"properties\": {\n                \"apiClientID\": {\n                    \"type\": \"number\",\n                    \"description\": \"internal ID for the API client\"\n                },\n                \"clientKey\": {\n                    \"type\": \"string\",\n                    \"description\": \"temporary random api key string\"\n                },\n                \"shortname\": {\n                    \"type\": \"string\",\n                    \"description\": \"a string describing the client\"\n                },\n                \"accesslevel\": {\n                    \"type\": \"string\",\n                    \"description\": \"access level of the api key\",\n                    \"enum\": [\n                        \"public\",\n                        \"callcenter\",\n                        \"intern\",\n                        \"blocked\"\n                    ]\n                },\n                \"lastChange\": {\n                    \"type\": \"number\",\n                    \"description\": \"unix timestamp representing the creating time of quota\",\n                    \"example\": 1459512840\n                }\n            }\n        },\n        \"captcha\": {\n            \"type\": \"object\",\n            \"description\": \"A message part to send. For images an other binary files, the content can be encoded as base64.\",\n            \"example\": {\n                \"queueId\": 1234,\n                \"mime\": \"text\\/html\",\n                \"content\": \"<h1>Title<\\/h1><p>Message<\\/p>\",\n                \"base64\": false\n            },\n            \"required\": [\n                \"mime\",\n                \"content\"\n            ],\n            \"additionalProperties\": false,\n            \"properties\": {\n                \"queueId\": {\n                    \"type\": \"number\",\n                    \"description\": \"optional ID of queued message item, this part belongs to\"\n                },\n                \"mime\": {\n                    \"type\": \"string\",\n                    \"description\": \"The mime type used in 'Content-Type', should include charset if necessary. If no charset is given, utf-8 is expected.\"\n                },\n                \"content\": {\n                    \"type\": \"string\",\n                    \"description\": \"content to transfer\"\n                },\n                \"base64\": {\n                    \"type\": \"boolean\",\n                    \"default\": false,\n                    \"description\": \"True if the content is encoded as base64.\"\n                }\n            }\n        },\n        \"quota\": {\n            \"type\": \"array\",\n            \"items\": {\n                \"type\": \"object\",\n                \"properties\": {\n                    \"route\": {\n                        \"type\": \"string\",\n                        \"description\": \"path of an URL for which the quota is valid\"\n                    },\n                    \"period\": {\n                        \"type\": \"string\",\n                        \"description\": \"Period of time for this quota\",\n                        \"enum\": [\n                            \"minute\",\n                            \"hour\",\n                            \"day\",\n                            \"week\",\n                            \"month\"\n                        ]\n                    },\n                    \"requests\": {\n                        \"type\": \"number\",\n                        \"description\": \"Number of requests left\",\n                        \"example\": 99\n                    },\n                    \"ts\": {\n                        \"type\": \"number\",\n                        \"description\": \"unix timestamp representing the creating time of quota\",\n                        \"example\": 1459512840\n                    }\n                }\n            }\n        },\n        \"createIP\": {\n            \"type\": \"string\",\n            \"description\": \"IP Address of the creator\"\n        },\n        \"ts\": {\n            \"type\": \"number\",\n            \"description\": \"unix timestamp representing the creating time of quota\",\n            \"example\": 1459512840\n        }\n    }\n}","{\n    \"type\": \"object\",\n    \"description\": \"An appointment represents a given time on a scope for defining appointments in a calendar.\",\n    \"example\": {\n        \"date\": 1447869172,\n        \"scope\": {\n            \"id\": 123\n        },\n        \"slotCount\": 2\n    },\n    \"required\": [\n        \"date\",\n        \"slotCount\",\n        \"scope\"\n    ],\n    \"additionalProperties\": false,\n    \"properties\": {\n        \"availability\": {\n            \"type\": \"object\",\n            \"description\": \"An Availability is a representation of opening hours for a scope. It defines the time a scope offers appointments and a ticket printer is able to serve process numbers.\",\n            \"example\": {\n                \"bookable\": {\n                    \"startInDays\": 2,\n                    \"endInDays\": 60\n                },\n                \"description\": \"Sonderöffnungszeit\",\n                \"endDate\": 1447919116,\n                \"endTime\": \"15:30\",\n                \"id\": 1234,\n                \"multipleSlotsAllowed\": true,\n                \"type\": \"appointment\",\n                \"repeat\": {\n                    \"afterWeeks\": 0\n                },\n                \"scope\": {\n                    \"id\": 141\n                },\n                \"slotTimeInMinutes\": 12,\n                \"startDate\": 1447919543,\n                \"startTime\": \"10:00\",\n                \"weekday\": {\n                    \"thursday\": true\n                },\n                \"workstationCount\": {\n                    \"callcenter\": 8,\n                    \"intern\": 10,\n                    \"public\": 3\n                }\n            },\n            \"required\": [\n                \"startDate\",\n                \"endDate\",\n                \"scope\",\n                \"type\",\n                \"weekday\"\n            ],\n            \"additionalProperties\": false,\n            \"properties\": {\n                \"bookable\": {\n                    \"type\": \"object\",\n                    \"properties\": {\n                        \"startInDays\": {\n                            \"type\": \"number\",\n                            \"default\": 1,\n                            \"description\": \"number of days relative to today to start offering appointments\"\n                        },\n                        \"endInDays\": {\n                            \"type\": \"number\",\n                            \"default\": 60,\n                            \"description\": \"maximum number of days in the future to offer appointments\"\n                        }\n                    }\n                },\n                \"description\": {\n                    \"type\": \"string\",\n                    \"description\": \"short note for internal usage\"\n                },\n                \"endDate\": {\n                    \"type\": \"number\",\n                    \"description\": \"unix timestamp of a day until this availability is valid\"\n                },\n                \"endTime\": {\n                    \"type\": \"string\",\n                    \"default\": \"23:59\",\n                    \"description\": \"format '0:00' or '16:30'\"\n                },\n                \"id\": {\n                    \"type\": [\n                        \"number\",\n                        \"null\"\n                    ],\n                    \"description\": \"ID for the availability. A NULL or zero means, that the availability is new.\"\n                },\n                \"lastChange\": {\n                    \"type\": \"number\",\n                    \"description\": \"unix timestamp of the last change on this availability\"\n                },\n                \"multipleSlotsAllowed\": {\n                    \"type\": [\n                        \"boolean\",\n                        \"number\"\n                    ],\n                    \"default\": true,\n                    \"description\": \"an appointment is allowed to take more than one time slot\"\n                },\n                \"processingNote\": {\n                    \"type\": \"array\",\n                    \"items\": {\n                        \"type\": \"string\",\n                        \"description\": \"Non persistent note usable for processing or logging calculation results, usually used for debugging\"\n                    }\n                },\n                \"repeat\": {\n                    \"type\": \"object\",\n                    \"properties\": {\n                        \"afterWeeks\": {\n                            \"type\": \"number\",\n                            \"description\": \"number of weeks for repeating the times, usually 1, 2 or 3\"\n                        },\n                        \"weekOfMonth\": {\n                            \"type\": \"number\",\n                            \"description\": \"number of week in month, on a value of 5 the last week of the month, even it is the 4th\"\n                        }\n                    }\n                },\n                \"scope\": {\n                    \"$ref\": \"scope.json\"\n                },\n                \"slotTimeInMinutes\": {\n                    \"type\": \"number\",\n                    \"default\": 10,\n                    \"description\": \"Multiplicated with a slotCount from an appointment this gives the duration in minutes for a appointment\\/process.\"\n                },\n                \"startDate\": {\n                    \"type\": \"number\",\n                    \"description\": \"unix timestamp of a day to start offering appointments\"\n                },\n                \"startTime\": {\n                    \"type\": \"string\",\n                    \"description\": \"format '0:00' or '17:30'\"\n                },\n                \"type\": {\n                    \"type\": \"string\",\n                    \"enum\": [\n                        \"appointment\",\n                        \"openinghours\",\n                        \"break\"\n                    ],\n                    \"description\": \"The following type are available\\n* appointment - defines times for appointments\\n* openinghours - defines times where a scope is opened\\n* break - defines times for a break (not implemented yet)\\n\"\n                },\n                \"weekday\": {\n                    \"type\": \"object\",\n                    \"properties\": {\n                        \"monday\": {\n                            \"default\": false,\n                            \"type\": [\n                                \"boolean\",\n                                \"number\"\n                            ]\n                        },\n                        \"tuesday\": {\n                            \"default\": false,\n                            \"type\": [\n                                \"boolean\",\n                                \"number\"\n                            ]\n                        },\n                        \"wednesday\": {\n                            \"default\": false,\n                            \"type\": [\n                                \"boolean\",\n                                \"number\"\n                            ]\n                        },\n                        \"thursday\": {\n                            \"default\": false,\n                            \"type\": [\n                                \"boolean\",\n                                \"number\"\n                            ]\n                        },\n                        \"friday\": {\n                            \"default\": false,\n                            \"type\": [\n                                \"boolean\",\n                                \"number\"\n                            ]\n                        },\n                        \"saturday\": {\n                            \"default\": false,\n                            \"type\": [\n                                \"boolean\",\n                                \"number\"\n                            ]\n                        },\n                        \"sunday\": {\n                            \"default\": false,\n                            \"type\": [\n                                \"boolean\",\n                                \"number\"\n                            ]\n                        }\n                    }\n                },\n                \"workstationCount\": {\n                    \"type\": \"object\",\n                    \"properties\": {\n                        \"callcenter\": {\n                            \"type\": \"number\",\n                            \"default\": 0,\n                            \"description\": \"number of workstations to handle appointments if handed out to the client by a callcenter\"\n                        },\n                        \"intern\": {\n                            \"type\": \"number\",\n                            \"default\": 0,\n                            \"description\": \"maximum of workstations expected to handle appointments\"\n                        },\n                        \"public\": {\n                            \"type\": \"number\",\n                            \"default\": 0,\n                            \"description\": \"number of workstations to offer appointments for booking using a public website\"\n                        }\n                    }\n                }\n            }\n        },\n        \"date\": {\n            \"type\": \"number\",\n            \"description\": \"unix timestamp representing the date and time of the appointment\"\n        },\n        \"scope\": {\n            \"type\": \"object\",\n            \"description\": \"A scope is the central unit for processing requests for clients. It is usally a building or a special location offering workstations to serve the clients. According to the availabilities a scope has, appointments are possible. With a calldisplay and a ticketprinter it can serve clients without an appointment.\",\n            \"example\": {\n                \"contact\": {\n                    \"city\": \"Schönefeld\",\n                    \"country\": \"Germany\",\n                    \"lat\": 52.345,\n                    \"lon\": 13.456,\n                    \"name\": \"Flughafen Schönefeld, Landebahn\",\n                    \"postalCode\": \"15831\",\n                    \"region\": \"Brandenburg\",\n                    \"street\": \"Zaunstraße\",\n                    \"streetNumber\": \"1\"\n                },\n                \"hint\": \"dritte Tür rechts\",\n                \"id\": 123,\n