456,\n                        \"name\": \"Flughafen Schönefeld, Aufsicht\",\n                        \"source\": \"dldb\"\n                    },\n                    \"shortName\": \"Zentrale\",\n                    \"status\": {\n                        \"emergency\": {\n                            \"activated\": false\n                        },\n                        \"queue\": {\n                            \"givenNumberCount\": 23,\n                            \"ghostWorkstationCount\": \"-1\",\n                            \"workstationCount\": 1,\n                            \"lastGivenNumber\": 322,\n                            \"lastGivenNumberTimestamp\": 1447925159\n                        },\n                        \"ticketprinter\": {\n                            \"deactivated\": false\n                        },\n                        \"availability\": {\n                            \"isOpened\": false\n                        }\n                    }\n                },\n                \"required\": [\n                    \"provider\",\n                    \"shortName\"\n                ],\n                \"additionalProperties\": false,\n                \"properties\": {\n                    \"contact\": {\n                        \"$ref\": \"contact.json\"\n                    },\n                    \"dayoff\": {\n                        \"type\": \"array\",\n                        \"items\": {\n                            \"$ref\": \"dayoff.json\"\n                        }\n                    },\n                    \"hint\": {\n                        \"type\": \"string\",\n                        \"description\": \"hint for the client like a description where to find the scope\",\n                        \"default\": \"\"\n                    },\n                    \"id\": {\n                        \"type\": \"number\",\n                        \"description\": \"auto increment\"\n                    },\n                    \"source\