taURL = function(width, height, getPixel) {\n    var gif = gifImage(width, height);\n    for (var y = 0; y < height; y += 1) {\n      for (var x = 0; x < width; x += 1) {\n        gif.setPixel(x, y, getPixel(x, y) );\n      }\n    }\n\n    var b = byteArrayOutputStream();\n    gif.write(b);\n\n    var base64 = base64EncodeOutputStream();\n    var bytes = b.toByteArray();\n    for (var i = 0; i < bytes.length; i += 1) {\n      base64.writeByte(bytes[i]);\n    }\n    base64.flush();\n\n    return 'data:image/gif;base64,' + base64;\n  };\n\n  //---------------------------------------------------------------------\n  // returns qrcode function.\n\n  return qrcode;\n}();\n\n// multibyte support\n!function() {\n\n  qrcode.stringToBytesFuncs['UTF-8'] = function(s) {\n    // http://stackoverflow.com/questions/18729405/how-to-convert-utf8-string-to-byte-array\n    function toUTF8Array(str) {\n      var utf8 = [];\n      for (var i=0; i < str.length; i++) {\n        var charcode = str.charCodeAt(i);\n        if (charcode < 0x80) utf8.push(charcode);\n        else if (charcode < 0x800) {\n          utf8.push(0xc0 | (charcode >> 6),\n              0x80 | (charcode & 0x3f));\n        }\n        else if (charcode < 0xd800 || charcode >= 0xe000) {\n          utf8.push(0xe0 | (charcode >> 12),\n              0x80 | ((charcode>>6) & 0x3f),\n              0x80 | (charcode & 0x3f));\n        }\n        // surrogate pair\n        else {\n          i++;\n          // UTF-16 encodes 0x10000-0x10FFFF by\n          // subtracting 0x10000 and splitting the\n          // 20 bits of 0x0-0xFFFFF into two halves\n          charcode = 0x10000 + (((charcode & 0x3ff)<<10)\n            | (str.charCodeAt(i) & 0x3ff));\n          utf8.push(0xf0 | (charcode >>18),\n              0x80 | ((charcode>>12) & 0x3f),\n              0x80 | ((charcode>>6) & 0x3f),\n              0x80 | (charcode & 0x3f));\n        }\n      }\n      return utf8;\n    }\n    return toUTF8Array(s);\n  };\n\n}();\n\n(function (factory) {\n  if (typeof define === 'function' && define.amd) {\n      define([], factory);\n  } else if (typeof exports === 'object') {\n      module.exports = factory();\n  }\n}(function () {\n    return qrcode;\n}));\n","import React, { useRef, useEffect } from 'react'\nimport qrGenerator from \"qrcode-generator\"\nimport PropTypes from 'prop-types'\n\nconst QrCodeComponent = props => {\n\n    const canvasRef = useRef(null)\n\n    const drawQrCode = (canvas, options) => {\n        qrGenerator.stringToBytes = qrGenerator.stringToBytesFuncs['UTF-8']\n        const codeObj = qrGenerator(options.version, options.ecLevel)\n        codeObj.addData(options.text)\n        codeObj.make()\n\n        let ctx = canvas.getContext('2d')\n        ctx.fillStyle = options.backgroundColor\n        ctx.fillRect(0, 0, options.size, options.size)\n\n        const gridSize = codeObj.getModuleCount()\n        const blockSize = options.size / (gridSize + 2 * options.quiet)\n        const offset = options.quiet * blockSize\n\n        ctx.beginPath()\n        ctx.fillStyle = options.fillColor\n        for (let row = 0; row < gridSize; row += 1) {\n            for (let col = 0; col < gridSize; col += 1) {\n                let top = offset + row * blockSize\n                let left = offset + col * blockSize\n\n                if (codeObj.isDark(row, col)) {\n                    ctx.rect(left, top, blockSize, blockSize)\n                }\n            }\n        }\n\n        ctx.fill()\n    }\n    \n    const options = {\n        version: 10,\n        ecLevel: 'M',\n        fillColor: '#000',\n        backgroundColor: '#fff',\n        quiet: 5,\n        size: props.width,\n        text: props.targetUrl\n    }\n\n    useEffect(() => {\n        drawQrCode(canvasRef.current, options)\n    }, [])\n    \n    return (<canvas ref={canvasRef} { ... props } />)\n}\n\nQrCodeComponent.propTypes = {\n    targetUrl: PropTypes.string,\n    width: PropTypes.string,\n    height: PropTypes.string\n}\n\nexport default QrCodeComponent","import React, { Component } from 'react'\nimport ReactToPrint, { PrintContextConsumer } from 'react-to-print';\nimport PropTypes from 'prop-types'\nimport FocusTrap from 'focus-trap-react'\nimport QrCodeComponent from './qrcode'\n\nclass QrCodeView extends Component {\n    constructor(props) {\n        super(props)\n        this.lightBoxRef = React.createRef();\n        this.handleTogglePopup = this.handleTogglePopup.bind(this);\n        this.handleClickOutside = this.handleClickOutside.bind(this);\n        this.keyDownHandler = this.keyDownHandler.bind(this);\n    }\n\n    componentDidMount() {\n        document.addEventListener(\"keydown\", this.keyDownHandler, true);\n        document.addEventListener(\"mousedown\", this.handleClickOutside);\n    }\n\n    componentWillUnmount() {\n        document.removeEventListener(\"keydown\", this.keyDownHandler, true);\n        document.removeEventListener(\"mousedown\", this.handleClickOutside);\n    }\n\n    handleClickOutside(event) {\n        if (this.lightBoxRef && !this.lightBoxRef.current.contains(event.target)) {\n            this.handleTogglePopup(event);\n        }\n    }\n\n    handleTogglePopup(event) {\n        event.preventDefault()\n        this.props.togglePopup()\n    }\n\n    keyDownHandler(event) {\n        if (event.key === \"Escape\") {\n            this.handleTogglePopup(event);\n        }\n    }\n\n    render() {\n        const headerstyles = {\n            backgroundColor: '#cccccc',\n            padding: '5px'\n        };\n        return (\n            <div className=\"lightbox\">\n                <FocusTrap>\n                    <div className=\"lightbox__content trap\" role=\"dialog\" aria-modal=\"true\" ref={this.lightBoxRef}>\n                        <div className=\"qrCodeView\">\n                            <div className=\"form-actions no-print\" style={headerstyles}>\n                                <ReactToPrint content={() => this.qrCodeRef}>\n                                    <PrintContextConsumer>\n                                        {({ handlePrint }) => (\n                                        <button \n                                            className=\"button\" \n                                            onClick={(event) => { event.preventDefault(); handlePrint(); }}>Drucken</button>\n                                        )}\n                                    </PrintContextConsumer>\n                                </ReactToPrint>\n                                <button className=\"button button--destructive\" onClick={(event) => { this.handleTogglePopup(event); }}>X</button>\n                            </div>\n                            <style>\n                                {`@media print {\n                                    .printContainer {\n                                        background-color: #ffffff;\n                                        display:flex;\n                                        justify-content:center;\n                                        align-items:center;\n                                        height:100%;\n                                    }\n                                    html, body{\n                                        height:100%;\n                                        width:100%;\n                                        }\n                                    }\n                                }`}\n                            </style>\n                            <div className=\"printContainer\" ref={el => (this.qrCodeRef = el)}>\n                                <QrCodeComponent width=\"400\" height=\"400\" className=\"qrCode\" { ... {'targetUrl' : this.props.targetUrl} } />\n                            </div>\n                        </div>\n                    </div>\n                </FocusTrap>\n            </div>\n        )\n    }\n}\n\nQrCodeView.propTypes = {\n    targetUrl: PropTypes.string,\n    togglePopup: PropTypes.func\n}\n\nexport default QrCodeView","import React, { Component } from 'react'\nimport PropTypes from 'prop-types'\n\nimport * as Inputs from '../../../lib/inputs'\nimport QrCodeView from \"../qrCode\";\n\nconst { FormGroup, Label, Controls, Select } = Inputs\n\nconst readPropsCluster = cluster => {\n    const { name, id } = cluster\n\n    return {\n        type: 'cluster',\n        id,\n        name\n    }\n}\n\nconst readPropsScope = scope => {\n    const { shortName, contact, id } = scope\n    return {\n        type: 'scope',\n        id,\n        shortName,\n        contact\n    }\n}\n\nclass CallDisplayConfigView extends Component {\n    constructor(props) {\n        super(props)\n        this.includeurl = props.includeurl || \"\";\n        //console.log('CallDisplayConfigView::constructor', props)\n\n        this.state = {\n            selectedItems: [],\n            departments: props.departments.map(department => {\n                const { name, id, scopes = [], clusters = [] } = department\n                return {\n                    name,\n                    id,\n                    scopes: scopes.map(readPropsScope),\n                    clusters: clusters.map(readPropsCluster)\n                }\n            }),\n            queueStatus: 'all',\n            template: 'defaultplatz',\n            hmac: '',\n            enableQrCode: false,\n            showQrCode: false\n        }\n\n        this.signParameters(this.state)\n    }\n\n    getSelectedItemsCollection(state) {\n        return state.selectedItems.reduce((carry, current) => {\n            if (current.type === \"cluster\") {\n                carry.clusterlist.push(current.id)\n            } else if (current.type === \"scope\") {\n                carry.scopelist.push(current.id)\n            }\n\n            return carry\n        }, {\n            scopelist: [],\n            clusterlist: []\n        })\n    }\n\n    buildHost() {\n        return document.location.origin;\n    }\n\n    buildCalldisplayUrl() {\n        const baseUrl  = this.props.config.calldisplay.baseUrl\n        let parameters = this.buildParameters(false);\n\n        return `${this.buildHost()}${baseUrl}?${parameters.join('&')}`\n    }\n\n    buildWebcalldisplayUrl() {\n        const baseUrl  = this.props.config.webcalldisplay.baseUrl\n        let parameters = this.buildParameters(true);\n\n        return `${this.buildHost()}${baseUrl}?${parameters.join('&')}`\n    }\n\n    buildParameters(hashParameters) {\n        const collections = this.getSelectedItemsCollection(this.state)\n        let queryParts = []\n\n        if (collections.scopelist.length > 0) {\n            queryParts.push(`collections[scopelist]=${collections.scopelist.join(\",\")}`)\n        }\n\n        if (collections.clusterlist.length > 0) {\n            queryParts.push(`collections[clusterlist]=${collections.clusterlist.join(\",\")}`)\n        }\n\n        if (this.state.queueStatus !== 'all') {\n            queryParts.push(`queue[status]=${this.state.queueStatus}`)\n        }\n\n        if (this.state.template !== 'default') {\n            queryParts.push(`template=${this.state.template}`)\n        }\n\n        if (! hashParameters && this.state.enableQrCode) {\n            queryParts.push(`qrcode=1`)\n        }\n\n        if (hashParameters) {\n            queryParts.push(`hmac=${this.state.hmac}`)\n        }\n\n        return queryParts\n    }\n\n    componentDidUpdate(prevProps, prevState) {\n        if (prevState.selectedItems !== this.state.selectedItems\n            || prevState.queueStatus !== this.state.queueStatus\n        ) {\n            this.signParameters(this.state)\n        }\n    }\n\n    signParameters(state) {\n        const collections = this.getSelectedItemsCollection(state)\n\n        let signingData = {\n            'section': 'webcalldisplay',\n            'parameters': {}\n        }\n\n        if (collections.scopelist.length > 0) {\n            signingData.parameters.collections = signingData.parameters.collections || {}\n            signingData.parameters.collections.scopelist = collections.scopelist.join(\",\")\n        }\n        if (collections.clusterlist.length > 0) {\n            signingData.parameters.collections = signingData.parameters.collections || {}\n            signingData.parameters.collections.clusterlist = collections.clusterlist.join(\",\")\n        }\n        if (this.state.queueStatus !== 'all') {\n            signingData.parameters.queue = {}\n            signingData.parameters.queue.status = this.state.queueStatus\n        }\n\n        const signParametersUrl = this.includeurl + '/sign/parameters/'\n        fetch(\n            signParametersUrl,\n            {\n                method: 'POST',\n                cache: 'no-cache',\n                headers: {'Accept': 'application/json', 'Content-Type': 'application/json'},\n                body: JSON.stringify(signingData)\n            }\n        ).then(response => response.json()).then(data => this.setState({ hmac: data.hmac }))\n    }\n\n    toggleQrCodeView() {\n        this.setState({\n            showQrCode: !this.state.showQrCode\n        });\n    }\n\n    renderCheckbox(enabled, onShowChange, label) {\n        const onChange = () => onShowChange(!enabled)\n\n        return (\n            <Inputs.Checkbox checked={enabled} {...{ onChange, label }} />\n        )\n    }\n\n    showItem(item) {\n        const items = this.state.selectedItems.filter(i => i.id !== item.id || (i.id == item.id && i.type !== item.type))\n        const newItem = Object.assign({}, item)\n        items.push(newItem)\n        this.setState({ selectedItems: items })\n    }\n\n    hideItem(item) {\n        const items = this.state.selectedItems.filter(i => i.id !== item.id || (i.id == item.id && i.type !== item.type))\n        this.setState({ selectedItems: items })\n    }\n\n    renderItem(item) {\n        const onChange = show => {\n            if (show) {\n                this.showItem(item)\n            } else {\n                this.hideItem(item)\n            }\n        }\n\n        const text = `${item.contact ? item.contact.name : item.name} ${item.shortName ? item.shortName : \"\"}`\n        const prefix = item.type === 'cluster' ? 'Cluster: ' : ''\n\n        const itemEnabled = this.state.selectedItems.reduce((carry, current) => {\n            return carry || (current.id === item.id && current.type === item.type)\n        }, false)\n        return (\n            <li>\n                <div key={item.id} className=\"form-check ticketprinter-config__item\">\n                    {this.renderCheckbox(itemEnabled, onChange, prefix + text)}\n                </div>\n            </li>\n        )\n    }\n\n    renderQrCodeEnabled() {\n        const onChange = () => {\n            this.setState({\n                enableQrCode: !this.state.enableQrCode\n            });\n        }\n        return (\n            <fieldset>\n                <legend className=\"label\">QR-Code für Aufrufanzeige</legend>\n                <div key=\"qrcodeEnabled\" className=\"form-check ticketprinter-config__item\">\n                    {this.renderCheckbox(this.state.enableQrCode, onChange, \"QR-Code anzeigen\")}\n                </div>\n            </fieldset>\n        )\n    }\n\n    renderScopes(scopes) {\n        if (scopes.length > 0) {\n            return (\n                <fieldset>\n                    <legend className=\"label\">Standorte</legend>\n                    <ul aria-label=\"Standortliste\" className=\"checkbox-list\">\n                    {scopes.map(this.renderItem.bind(this))}\n                    </ul>\n                </fieldset>\n            )\n        }\n    }\n\n    renderClusters(clusters) {\n        if (clusters.length > 0) {\n            return (\n                <fieldset>\n                    <legend className=\"label\">Standort­gruppe</legend>\n                    <ul aria-label=\"Standortclusterliste\" className=\"checkbox-list\">\n                    {clusters.map(this.renderItem.bind(this))}\n                    </ul>\n                </fieldset>\n            )\n        }\n    }\n\n    renderDepartment(department) {\n        return (\n            <div key={department.id}>\n                <h2 className=\"block__heading\">{department.name}</h2>\n                {this.renderScopes(department.scopes)}\n                {this.renderClusters(department.clusters)}\n            </div>\n        )\n    }\n\n    render() {\n        const calldisplayUrl = this.buildCalldisplayUrl()\n        const webcalldisplayUrl = this.buildWebcalldisplayUrl()\n\n        const onQueueStatusChange = (_, value) => {\n            this.setState({\n                queueStatus: value\n            })\n        }\n\n        const onTemplateStatusChange = (_, value) => {\n            this.setState({\n                template: value\n            })\n        }\n\n        return (\n            <form className=\"form--base form-group calldisplay-config\">\n                {this.state.departments.map(this.renderDepartment.bind(this))}\n                {this.renderQrCodeEnabled()}\n                <FormGroup>\n                    <Label \n                        attributes={{ \"htmlFor\": \"visibleCalls\" }} \n                        value=\"Angezeigte Aufrufe\">\n                    </Label>\n                    <Controls>\n                        <Select\n                            options={[{ name: 'Alle', value: 'all' }, { name: \"Nur Abholer\", value: 'pickup' }, { name: \"Spontan- und Terminkunden\", value: 'called' }]}\n                            value={this.state.queueStatus}\n                            attributes={{ \"id\": \"visibleCalls\" }}\n                            onChange={onQueueStatusChange} />\n                    </Controls>\n                </FormGroup>\n                <FormGroup>\n                    <Label attributes={{ \"htmlFor\": \"calldisplayLayout\" }} value=\"Layout\"></Label>\n                    <Controls>\n                        <Select\n                            attributes={{ \"id\": \"calldisplayLayout\" }}\n                            options={[\n                                { name: 'Uhrzeit, 6-12 Aufrufe | Platz', value: 'defaultplatz' },\n                                { name: 'Uhrzeit, 6-12 Aufrufe | Raum', value: 'defaultraum' },\n                                { name: 'Uhrzeit, 6 Aufrufe | Platz', value: 'clock5platz' },\n                                { name: 'Uhrzeit, Anzahl Wartende, 6-12 Aufrufe | Platz', value: 'clocknrplatz' },\n                                { name: 'Uhrzeit, Anzahl Wartende, 6-12 Aufrufe | Raum', value: 'clocknrraum' },\n                                { name: 'Uhrzeit, Anzahl Wartende, Wartezeit, 6-12 Aufrufe | Platz', value: 'clocknrwaitplatz' },\n                                { name: 'Uhrzeit, Anzahl Wartende, Wartezeit, 6-12 Aufrufe | Raum', value: 'clocknrwaitraum' },\n                                { name: '6-18 Aufrufe | Platz', value: 'raw18platz' }\n                            ]}\n                            value={this.state.template}\n                            onChange={onTemplateStatusChange} />\n                    </Controls>\n                </FormGroup>\n                <FormGroup>\n                    <Label attributes={{ \"htmlFor\": \"calldisplayUrl\" }} value=\"URL\"></Label>\n                    <Controls>\n                        <Inputs.Text\n                            value={calldisplayUrl}\n                            attributes={{ readOnly: true, id: \"calldisplayUrl\" }} />\n                    </Controls>\n                </FormGroup>\n                <div className=\"form-actions\">\n                    <a href={calldisplayUrl} target=\"_blank\" rel=\"noopener noreferrer\" className=\"button button-submit\"><i className=\"fas fa-external-link-alt\" aria-hidden=\"true\"></i> Aktuelle Konfiguration in einem neuen Fenster öffnen</a>\n                </div>\n                <FormGroup>\n                    <Label attributes={{ \"htmlFor\": \"webcalldisplayUrl\" }} value=\"Webcall Display URL\"></Label>\n                    <Controls>\n                        <Inputs.Text\n                            value={webcalldisplayUrl}\n                            attributes={{ readOnly: true, id: \"webcalldisplayUrl\" }} />\n                    </Controls>\n                </FormGroup>\n                <div className=\"form-actions\">\n                    <button className=\"button\" aria-hidden=\"true\" onClick={(event) => {event.preventDefault(); this.toggleQrCodeView();}}>QR-Code anzeigen / drucken</button>\n                    <a href={webcalldisplayUrl} target=\"_blank\" rel=\"noopener noreferrer\" className=\"button button-submit\"><i className=\"fas fa-external-link-alt\" aria-hidden=\"true\"></i> in der mobilen Anzeige öffnen</a>\n                </div>\n                { this.state.showQrCode ? <QrCodeView text='QrCode für die mobile Ansicht des Aufrufsystems' targetUrl={webcalldisplayUrl} togglePopup={this.toggleQrCodeView.bind(this)} /> : null }\n            </form>\n        )\n    }\n}\n\nCallDisplayConfigView.propTypes = {\n    includeurl: PropTypes.string,\n    departments: PropTypes.array,\n    organisation: PropTypes.object,\n    config: PropTypes.shape({\n        calldisplay: PropTypes.object,\n        webcalldisplay: PropTypes.object\n    })\n}\n\nexport default CallDisplayConfigView\n","import React, { Component } from 'react'\nimport PropTypes from 'prop-types'\nimport * as Inputs from '../../lib/inputs'\n\nclass MandantView extends Component {\n    constructor(props) {\n        super(props)\n    }\n\n    componentDidUpdate() {\n        //console.log(\"updated mandant component\")\n    }\n\n    render() {\n        const onChange = (field, value) => {\n            if (field == 'source') {\n                value = value.substring(0, 10);\n            }\n            this.props.changeHandler(field, value)\n        }\n\n        return (\n            <div>\n                <div className=\"fieldset panel--heavy\">\n                    <Inputs.FormGroup>\n                        <Inputs.Label\n                            value={this.props.labelsmandant.label}\n                            attributes={{ \"htmlFor\": \"mandantLabel\" }}\n                        />\n                        <Inputs.Controls>\n                            <Inputs.Text\n                                name=\"label\"\n                                value={(this.props.source) ? this.props.source.label : ''}\n                                onChange={onChange}\n                                attributes={{ \"id\": \"mandantLabel\" }}\n                            />\n                        </Inputs.Controls>\n                    </Inputs.FormGroup>\n                    <Inputs.FormGroup>\n                        <Inputs.Label\n                            value={this.props.labelsmandant.source}\n                            attributes={{ \"htmlFor\": \"mandantSource\" }}\n                        />\n                        <Inputs.Controls>\n                            <Inputs.Text\n                                name=\"source\"\n                                value={(this.props.source) ? this.props.source.source : ''}\n                                attributes={{ readOnly: this.props.source.lastChange, maxLength: 10, \"id\": \"mandantSource\", \"aria-describedby\": \"help_mandantSource\" }}\n                                onChange={onChange}\n                            />\n                            <Inputs.Description\n                                value={this.props.descriptions.mandantlabel}\n                                attributes={{ \"id\": \"help_mandantSource\" }}\n                            />\n                        </Inputs.Controls>\n                    </Inputs.FormGroup>\n                </div>\n                <fieldset>\n                    <legend>{this.props.labelsmandant.contact}</legend>\n                    <div className=\"panel--heavy\">\n                        <Inputs.FormGroup>\n                            <Inputs.Label\n                                value={this.props.labelsmandant.name}\n                                attributes={{ \"htmlFor\": \"mandantContact\" }}\n                            />\n                            <Inputs.Controls>\n                                <Inputs.Text\n                                    name=\"contact[name]\"\n                                    value={(this.props.source.contact) ? this.props.source.contact.name : ''}\n                                    onChange={onChange}\n                                    attributes={{ \"id\": \"mandantContact\" }}\n                                />\n                            </Inputs.Controls>\n                        </Inputs.FormGroup>\n                        <Inputs.FormGroup>\n                            <Inputs.Label\n                                value={this.props.labelsmandant.email}\n                                attributes={{ \"htmlFor\": \"mandantEmail\" }}\n                            />\n                            <Inputs.Controls>\n                                <Inputs.Text\n                                    name=\"contact[email]\"\n                                    value={(this.props.source.contact) ? this.props.source.contact.email : ''}\n                                    onChange={onChange}\n                                    attributes={{ \"id\": \"mandantEmail\" }}\n                                />\n                            </Inputs.Controls>\n                        </Inputs.FormGroup>\n                    </div>\n                </fieldset>\n            </div>\n        )\n    }\n}\n\nMandantView.propTypes = {\n    labelsmandant: PropTypes.object.isRequired,\n    source: PropTypes.object.isRequired,\n    changeHandler: PropTypes.func,\n    descriptions: PropTypes.object\n}\n\nexport default MandantView\n","import React, { Component } from 'react'\nimport PropTypes from 'prop-types'\nimport $ from \"jquery\"\nimport * as Inputs from '../../lib/inputs'\nimport { getEntity } from '../../lib/schema'\n\nconst renderRequest = (request, index, onChange, onDeleteClick, labels, descriptions, source) => {\n    const formName = `requests[${index}]`\n\n    return (\n        <tr key={index} className=\"request-item\">\n            <td className=\"request-item__id\" width=\"auto\">\n                <Inputs.Text\n                    name={`${formName}[id]`}\n                    placeholder={labels.id}\n                    value={request.id}\n                    attributes={{ \"readOnly\": \"1\", \"aria-label\": \"Laufende Nummer\" }}\n                />\n            </td>\n            <td className=\"request-item__name\" width=\"auto\">\n                <Inputs.Text\n                    name={`${formName}[name]`}\n                    placeholder={labels.name}\n                    value={request.name}\n                    onChange={onChange}\n                    attributes={{ \"aria-label\": \"Bezeichnung\" }}\n                />\n            </td>\n            <td className=\"request-item__link\">\n                <Inputs.FormGroup>\n                    <Inputs.Label\n                        value={`${labels.url}`}\n                        attributes={{ \"htmlFor\": `requestUrl${index}` }}\n                    />\n                    <Inputs.Controls>\n                        <Inputs.Text\n                            name={`${formName}[link]`}\n                            placeholder={labels.url}\n                            value={request.link}\n                            onChange={onChange}\n                            attributes={{ \"id\": `requestUrl${index}` }}\n                        />\n                    </Inputs.Controls>\n                </Inputs.FormGroup>\n                <Inputs.FormGroup>\n                    <Inputs.Label\n                        value={labels.group}\n                        attributes={{ \"htmlFor\": `requestGroup${index}` }}\n                    />\n                    <Inputs.Controls>\n                        <Inputs.Text\n                            name={`${formName}[group]`}\n                            placeholder={labels.group}\n                            value={request.group}\n                            onChange={onChange}\n                            attributes={{ \"id\": `requestGroup${index}` }}\n                        />\n                    </Inputs.Controls>\n                </Inputs.FormGroup>\n                <Inputs.FormGroup>\n                    <Inputs.Label\n                        value={labels.data}\n                        attributes={{ \"htmlFor\": `requestData${index}` }}\n                    />\n                    <Inputs.Controls>\n                        <Inputs.Textarea\n                            name={`${formName}[data]`}\n                            value={(request.data) ? JSON.stringify(request.data) : ''}\n                            placeholder='{}'\n                            onChange={onChange}\n                            attributes={{ \"id\": `requestData${index}`, \"aria-describedby\": `help_requestData${index}` }}\n                        />\n                        <Inputs.Description\n                            value={descriptions.data}\n                            attributes={{ \"id\": `help_requestData${index}` }}\n                        />\n                    </Inputs.Controls>\n                </Inputs.FormGroup>\n                <Inputs.Hidden\n                    name={`${formName}[source]`}\n                    value={source}\n                />\n            </td>\n            <td className=\"request-item__delete\">\n                <div className=\"form-check\">\n                    <label className=\"checkboxdeselect request__delete-button form-check-label\">\n                        <input className=\"form-check-input\" type=\"checkbox\" readOnly={true} checked={true} onClick={() => onDeleteClick(index)} role=\"button\" />\n                        <span>Löschen</span>\n                    </label>\n                </div>\n            </td>\n        </tr >\n    )\n}\n\nclass RequestsView extends Component {\n    constructor(props) {\n        super(props)\n    }\n\n    getNextId() {\n        let nextId = Number(this.props.source.requests.length ? this.props.source.requests[this.props.source.requests.length - 1].id : 0) + 1\n        return nextId;\n    }\n\n    getRequestsWithLabels(onChange, onDeleteClick) {\n        return this.props.source.requests.map((request, index) => renderRequest(request, index, onChange, onDeleteClick, this.props.labelsrequests, this.props.descriptions, this.props.source.source))\n    }\n\n    hideDeleteButton() {\n        $('.request-item').each((index, item) => {\n            if ($(item).find('.request-item__id input').val()) {\n                $(item).find('.request__delete-button').css(\"visibility\", \"hidden\");\n            }\n        })\n    }\n\n    componentDidMount() {\n        console.log(\"mounted request component\")\n        this.hideDeleteButton()\n    }\n\n    componentDidUpdate() {\n        //console.log(\"updated request component\")\n    }\n\n    render() {\n        const onNewClick = ev => {\n            ev.preventDefault()\n            getEntity('request').then((entity) => {\n                entity.id = this.getNextId()\n                entity.source = this.props.source.source\n                this.props.addNewHandler('requests', [entity])\n            })\n        }\n\n        const onDeleteClick = index => {\n            this.props.deleteHandler('requests', index)\n        }\n\n        const onChange = (field, value) => {\n            this.props.changeHandler(field, value)\n        }\n\n        return (\n            <div className=\"table-responsive-wrapper requests__list\" aria-live=\"polite\" id=\"liveregionRequestList\">\n                <table className=\"table--base\">\n                    <thead>\n                        <tr>\n                            <th>LfdNr.</th>\n                            <th>Bezeichnung</th>\n                            <th>Link und weitere Daten</th>\n                            <th>Löschen</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        {this.getRequestsWithLabels(onChange, onDeleteClick)}\n                    </tbody>\n                    <tfoot>\n                        <tr>\n                            <td colSpan=\"4\">\n                                <p>\n                                    <Inputs.Description\n                                        value={this.props.descriptions.delete}\n                                    />\n                                </p>\n                            </td>\n                        </tr>\n                    </tfoot>\n                </table>\n                <div className=\"table-actions\">\n                    <button className=\"link button-default\" onClick={onNewClick}><i className=\"fas fa-plus-square color-positive\" aria-hidden=\"true\"></i> Neue Dienstleistung</button>\n                </div>\n            </div>\n        )\n    }\n}\n\nRequestsView.propTypes = {\n    labelsrequests: PropTypes.object.isRequired,\n    descriptions: PropTypes.object.isRequired,\n    source: PropTypes.object.isRequired,\n    changeHandler: PropTypes.func,\n    addNewHandler: PropTypes.func,\n    deleteHandler: PropTypes.func\n}\n\nexport default RequestsView\n","import React, { Component } from 'react'\nimport PropTypes from 'prop-types'\nimport $ from \"jquery\"\nimport * as Inputs from '../../lib/inputs'\nimport { getEntity } from '../../lib/schema'\n\nconst renderProvider = (provider, index, onChange, onDeleteClick, labels, descriptions, source) => {\n    const formName = `providers[${index}]`\n\n    return (\n        <tr key={index} className=\"provider-item\">\n            <td className=\"provider-item__id\" width=\"auto\">\n                <Inputs.Text\n                    name={`${formName}[id]`}\n                    placeholder={labels.id}\n                    value={provider.id}\n                    attributes={{ \"readOnly\": \"1\", \"aria-label\": \"Laufende Nummer\" }}\n                />\n            </td>\n            <td className=\"provider-item__name\" width=\"auto\">\n                <Inputs.Text\n                    name={`${formName}[name]`}\n                    placeholder={labels.name}\n                    value={provider.name}\n                    onChange={onChange}\n                    attributes={{ \"aria-label\": \"Bezeichnung\" }}\n                />\n            </td>\n            <td className=\"provider-item__link\">\n                <Inputs.FormGroup>\n                    <Inputs.Label\n                        value={`${labels.url}`}\n                        attributes={{ \"htmlFor\": `providersUrl${index}` }}\n                    />\n                    <Inputs.Controls>\n                        <Inputs.Text\n                            name={`${formName}[link]`}\n                            placeholder={labels.url}\n                            value={provider.link}\n                            onChange={onChange}\n                            attributes={{ \"id\": `providersUrl${index}` }}\n                        />\n                    </Inputs.Controls>\n                </Inputs.FormGroup>\n                <Inputs.FormGroup>\n                    <Inputs.Label\n                        value={labels.street}\n                        attributes={{ \"htmlFor\": `providersStreet${index}` }}\n                    />\n                    <Inputs.Controls>\n                        <Inputs.Text\n                            name={`${formName}[contact][street]`}\n                            placeholder={labels.street}\n                            value={provider.contact.street}\n                            onChange={onChange}\n                            attributes={{ \"id\": `providersStreet${index}` }}\n                        />\n                    </Inputs.Controls>\n                </Inputs.FormGroup>\n                <Inputs.FormGroup>\n                    <Inputs.Label\n                        value={labels.streetNumber}\n                        attributes={{ \"htmlFor\": `providersStreetnumber${index}` }}\n                    />\n                    <Inputs.Controls>\n                        <Inputs.Text\n                            name={`${formName}[contact][streetNumber]`}\n                            placeholder={labels.streetNumber}\n                            value={provider.contact.streetNumber}\n                            onChange={onChange}\n                            attributes={{ \"id\": `providersStreetnumber${index}` }}\n                        />\n                    </Inputs.Controls>\n                </Inputs.FormGroup>\n                <Inputs.FormGroup>\n                    <Inputs.Label\n                        value={labels.postalCode}\n                        attributes={{ \"htmlFor\": `providersPostalcode${index}` }}\n                    />\n                    <Inputs.Controls>\n                        <Inputs.Text\n                            name={`${formName}[contact][postalCode]`}\n                            placeholder={labels.postalCode}\n                            value={provider.contact.postalCode}\n                            onChange={onChange}\n                            attributes={{ \"id\": `providersPostalcode${index}` }}\n                        />\n                    </Inputs.Controls>\n                </Inputs.FormGroup>\n                <Inputs.FormGroup>\n                    <Inputs.Label\n                        value={labels.city}\n                        attributes={{ \"htmlFor\": `providersCity${index}` }}\n                    />\n                    <Inputs.Controls>\n                        <Inputs.Text\n                            name={`${formName}[contact][city]`}\n                            placeholder={labels.city}\n                            value={provider.contact.city}\n                            onChange={onChange}\n                            attributes={{ \"id\": `providersCity${index}` }}\n                        />\n                    </Inputs.Controls>\n                </Inputs.FormGroup>\n                <Inputs.FormGroup>\n                    <Inputs.Label\n                        value={labels.data}\n                        attributes={{ \"htmlFor\": `providersData${index}` }}\n                    />\n                    <Inputs.Controls>\n                        <Inputs.Textarea\n                            name={`${formName}[data]`}\n                            value={(provider.data) ? JSON.stringify(provider.data) : ''}\n                            placeholder='{}'\n                            onChange={onChange}\n                            attributes={{ \"id\": `providersData${index}`, \"aria-describedby\": `help_providersData${index}` }}\n                        />\n                        <Inputs.Description\n                            value={descriptions.data}\n                            attributes={{ \"id\": `help_providersData${index}` }}\n                        />\n                    </Inputs.Controls>\n                </Inputs.FormGroup>\n                <Inputs.Hidden\n                    name={`${formName}[source]`}\n                    value={source}\n                />\n            </td>\n            <td className=\"provider-item__delete\">\n                <div className=\"form-check\">\n                    <label className=\"checkboxdeselect provider__delete-button form-check-label\">\n                        <input className=\"form-check-input\" type=\"checkbox\" readOnly={true} checked={true} onClick={() => onDeleteClick(index)} role=\"button\" aria-label=\"Diesen Datensatz löschen\" />\n                        <span>Löschen</span>\n                    </label>\n                </div>\n            </td>\n        </tr >\n    )\n}\n\nclass ProvidersView extends Component {\n    constructor(props) {\n        super(props)\n    }\n\n    getNextId() {\n        let nextId = Number(this.props.source.providers.length ? this.props.source.providers[this.props.source.providers.length - 1].id : 0) + 1\n        return nextId;\n    }\n\n    getProvidersWithLabels(onChange, onDeleteClick) {\n        return this.props.source.providers.map((provider, index) => renderProvider(provider, index, onChange, onDeleteClick, this.props.labelsproviders, this.props.descriptions, this.props.source.source))\n    }\n\n    hideDeleteButton() {\n        $('.provider-item').each((index, item) => {\n            if ($(item).find('.provider-item__id input').val()) {\n                $(item).find('.provider__delete-button').css(\"visibility\", \"hidden\");\n            }\n        })\n    }\n\n    componentDidMount() {\n        console.log(\"mounted provider component\")\n        this.hideDeleteButton()\n    }\n\n    componentDidUpdate() {\n        //console.log(\"updated provider component\")\n    }\n\n    render() {\n        const onNewClick = ev => {\n            ev.preventDefault()\n            getEntity('provider').then((entity) => {\n                entity.id = this.getNextId()\n                entity.source = this.props.source.source\n                this.props.addNewHandler('providers', [entity])\n            })\n        }\n\n        const onDeleteClick = index => {\n            this.props.deleteHandler('providers', index)\n        }\n\n        const onChange = (field, value) => {\n            this.props.changeHandler(field, value)\n        }\n\n        return (\n            <div className=\"table-responsive-wrapper department-providers__list\" aria-live=\"polite\" id=\"liveregionProvidersList\">\n                <table className=\"table--base\">\n                    <thead>\n                        <tr>\n                            <th>LfdNr.</th>\n                            <th>Bezeichnung</th>\n                            <th>Link und weitere Daten</th>\n                            <th></th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        {this.getProvidersWithLabels(onChange, onDeleteClick)}\n                    </tbody>\n                    <tfoot>\n                        <tr>\n                            <td colSpan=\"4\">\n                                <p>\n                                    <Inputs.Description\n                                        value={this.props.descriptions.delete}\n                                    />\n                                </p>\n                            </td>\n                        </tr>\n                    </tfoot>\n                </table>\n                <div className=\"table-actions\">\n                    <button className=\"link button-default\" onClick={onNewClick}><i className=\"fas fa-plus-square color-positive\" aria-hidden=\"true\"></i> Neuer Dienstleister</button>\n                </div>\n            </div>\n        )\n    }\n}\n\nProvidersView.propTypes = {\n    labelsproviders: PropTypes.object.isRequired,\n    descriptions: PropTypes.object.isRequired,\n    source: PropTypes.object.isRequired,\n    changeHandler: PropTypes.func,\n    addNewHandler: PropTypes.func,\n    deleteHandler: PropTypes.func\n}\n\nexport default ProvidersView\n","import React, { Component } from 'react'\nimport PropTypes from 'prop-types'\nimport * as Inputs from '../../lib/inputs'\nimport { getEntity } from '../../lib/schema'\n\nclass RequestRelationView extends Component {\n    constructor(props) {\n        super(props)\n    }\n\n    componentDidUpdate() {\n        //console.log(\"updated requestrelation component\")\n    }\n\n    getRequestRelation(onChange, onDeleteClick) {\n        return this.props.source.requestrelation.map((item, index) => this.renderItem(item, index, onChange, onDeleteClick, this.props.source))\n    }\n\n    renderOption(item) {\n        return {\n            name: item.name ? item.name : this.props.labelsrequestrelation.noName, value: item.id\n        }\n    }\n\n    renderItem(item, index, onChange, onDeleteClick) {\n        const formName = `requestrelation[${index}]`\n\n        return (\n            <tr key={index} className=\"request-item\">\n                <td className=\"requestrelation-item__request\">\n                    <Inputs.Hidden\n                        name={`${formName}[source]`}\n                        value={this.props.source.source}\n                    />\n                    <Inputs.Select\n                        value={item.request.id}\n                        name={`${formName}[request][id]`}\n                        {...{ onChange }}\n                        options={\n                            this.props.source.requests.map((request) => this.renderOption(request))\n                        } {...{ onChange }}\n                        attributes={{ \"aria-label\": this.props.labelsrequestrelation.request }}\n                    />\n                </td>\n                <td className=\"requestrelation-item__provider\">\n                    <Inputs.Select\n                        value={item.provider.id}\n                        name={`${formName}[provider][id]`}\n                        {...{ onChange }}\n                        options={\n                            this.props.source.providers.map((provider) => this.renderOption(provider))\n                        } {...{ onChange }}\n                        attributes={{ \"aria-label\": this.props.labelsrequestrelation.provider }}\n                    />\n                </td>\n                <td className=\"requestrelation-item__slots\">\n                    <Inputs.Text\n                        name={`${formName}[slots]`}\n                        value={(item.slots) ? item.slots : 1}\n                        onChange={onChange}\n                        attributes={{ \"aria-label\": this.props.labelsrequestrelation.slots }}\n                    />\n                </td>\n                <td className=\"request-item__delete\">\n                    <div className=\"form-check\">\n                        <label className=\"checkboxdeselect requestrelation__delete-button form-check-label\">\n                            <input className=\"form-check-input\" type=\"checkbox\" readOnly={true} checked=\"checked\" onClick={() => onDeleteClick(index)} role=\"button\" aria-label=\"Diesen Datensatz löschen\" />\n                            <span>Löschen</span>\n                        </label>\n                    </div>\n                </td>\n            </tr >\n        )\n    }\n\n    render() {\n        const onChange = (field, value) => {\n            this.props.changeHandler(field, value)\n        }\n\n        const onNewClick = ev => {\n            ev.preventDefault()\n            getEntity('requestrelation').then((entity) => {\n                entity.source = this.props.source.source\n                this.props.addNewHandler('requestrelation', [entity])\n            })\n        }\n\n        const onDeleteClick = index => {\n            this.props.deleteHandler('requestrelation', index)\n        }\n\n        return (\n            <fieldset>\n                <div className=\"requestrelation__list\" aria-live=\"polite\" id=\"liveregionRequestrelationList\">\n                    <table className=\"table--base\">\n                        <thead>\n                            <tr>\n                                <th>{this.props.labelsrequestrelation.request}</th>\n                                <th>{this.props.labelsrequestrelation.provider}</th>\n                                <th>{this.props.labelsrequestrelation.slots}</th>\n                                <th>{this.props.labelsrequestrelation.delete}</th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            {this.getRequestRelation(onChange, onDeleteClick)}\n                        </tbody>\n                        <tfoot>\n                            <tr>\n                                <td colSpan=\"4\">\n                                    <Inputs.Description\n                                        value={this.props.descriptions.requestrelation}\n                                    />\n                                </td>\n                            </tr>\n                        </tfoot>\n                    </table>\n                    <div className=\"table-actions\">\n                        <button className=\"link button-default requestrelation--new\" onClick={onNewClick}><i className=\"fas fa-plus-square color-positive\" aria-hidden=\"true\"></i> {this.props.labelsrequestrelation.new}</button>\n                    </div>\n                </div>\n            </fieldset>\n        )\n    }\n}\n\nRequestRelationView.propTypes = {\n    labelsrequestrelation: PropTypes.object.isRequired,\n    source: PropTypes.object.isRequired,\n    changeHandler: PropTypes.func,\n    addNewHandler: PropTypes.func,\n    deleteHandler: PropTypes.func,\n    descriptions: PropTypes.object\n}\n\nexport default RequestRelationView\n","import React, { Component } from 'react'\nimport PropTypes from 'prop-types'\nimport { deepMerge, makeNestedObj, getFieldList } from '../../lib/utils'\nimport MandantView from '../../block/source/mandant'\nimport RequestsView from '../../block/source/requests'\nimport ProvidersView from '../../block/source/providers'\nimport RequestRelationView from '../../block/source/requestrelations'\n\nclass SourceView extends Component {\n    constructor(props) {\n        super(props)\n        this.changeHandler = this.changeHandler.bind(this)\n        this.addNewHandler = this.addNewHandler.bind(this)\n        this.deleteHandler = this.deleteHandler.bind(this)\n    }\n\n    changeHandler(field, value) {\n        let newstate = this.props.source\n        const fieldList = getFieldList(field)\n        if (fieldList.length === 1) {\n            newstate[fieldList.pop()] = value\n        } else {\n            newstate = deepMerge(newstate, makeNestedObj(fieldList, value))\n        }\n        this.setState({ source: newstate });\n    }\n\n    addNewHandler(field, props) {\n        let newstate = this.props.source\n        newstate[field] = this.props.source[field].concat(props)\n        this.setState({ source: newstate })\n    }\n\n    deleteHandler(field, deleteIndex) {\n        let newstate = this.props.source\n        newstate[field] = this.props.source[field].filter((item, index) => {\n            return index !== deleteIndex\n        })\n        this.setState({ source: newstate })\n    }\n\n    componentDidMount() {\n        //console.log(\"mounted source component\")\n    }\n\n    componentDidUpdate() {\n        //console.log(\"updated source component\")\n    }\n\n    render() {\n        return (\n            <div>\n                <MandantView\n                    {...this.props}\n                    source={this.props.source}\n                    changeHandler={this.changeHandler}\n                />\n                <fieldset>\n                    <legend>Dienstleistungen</legend>\n                    <RequestsView\n                        {...this.props}\n                        source={this.props.source}\n                        changeHandler={this.changeHandler}\n                        addNewHandler={this.addNewHandler}\n                        deleteHandler={this.deleteHandler}\n                    />\n                </fieldset>\n                <fieldset>\n                    <legend>Dienstleister</legend>\n                    <ProvidersView\n                        {...this.props}\n                        source={this.props.source}\n                        changeHandler={this.changeHandler}\n                        addNewHandler={this.addNewHandler}\n                        deleteHandler={this.deleteHandler}\n                    />\n                </fieldset>\n                <fieldset>\n                    <legend>Zeitslots</legend>\n                    <RequestRelationView\n                        {...this.props}\n                        source={this.props.source}\n                        changeHandler={this.changeHandler}\n                        addNewHandler={this.addNewHandler}\n                        deleteHandler={this.deleteHandler}\n                    />\n                </fieldset>\n            </div>\n        );\n    }\n}\n\nSourceView.propTypes = {\n    source: PropTypes.object\n}\n\nexport default SourceView\n","export const sortByName = (a, b) => {\n    return (a['name'] > b['name']) - (a['name'] < b['name'])\n}","import React, { Component } from 'react'\nimport PropTypes from 'prop-types'\nimport * as Inputs from '../../lib/inputs'\nimport { loopWithCallback } from '../../lib/utils'\nimport { sortByName } from '../../lib/sort'\n\nclass SourceSelectView extends Component {\n    constructor(props) {\n        super(props)\n    }\n\n    componentDidUpdate() {\n        //console.log(\"updated component\", this.props.scopestate.provider)\n    }\n\n    render() {\n        const providerList = Object.values(this.props.scopestate.providerList)\n\n        const sourceList = Object.values(this.props.scopestate.sourcelist)\n\n        const sourceOptions = [{\n            \"value\": 0,\n            \"name\": this.props.labels.selectPlease\n        }].concat(sourceList.map((item) => {\n            return {\n                name: item.label, value: item.source\n            }\n        })).sort(sortByName)\n\n        const providerGroups = [{\n            'label': this.props.labels.selectPlease,\n            'options': [\n                { \"value\": 0, \"name\": this.props.labels.selectPlease }\n            ]\n        }].concat(providerList.map((group) => {\n            return {\n                label: this.props.labels[group.name],\n                options: Object.values(group.items).map(item => {\n                    return {\n                        name: item.name, value: item.id\n                    }\n                }).sort(sortByName)\n            }\n        }))\n\n        const onChangeProvider = (field, selectedProviderId) => {\n            this.props.changeHandler('provider', loopWithCallback(providerList, (group) => {\n                if (selectedProviderId != 0) {\n                    return Object.values(group.items).find(provider => provider.id === selectedProviderId)\n                }\n                return Object.values(group.items).find(provider => provider.id === this.props.scopestate.provider.id)\n            }))\n        }\n\n        const onChangeSource = (field, selectedSource) => {\n            if (selectedSource != 0) {\n                this.props.onChangeSourceHandler('providerList', selectedSource)\n                this.props.changeHandler('source', sourceList.find(source => source.source === selectedSource))\n            }\n        }\n\n        const hasProvider = () => {\n            return (this.props.scopestate.provider && this.props.scopestate.provider.id) ? true : false;\n        }\n\n        const hasSource = () => {\n            return (this.props.scopestate.source && this.props.scopestate.source.source) ? true : false;\n        }\n\n        return (\n            <fieldset className=\"panel--heavy\">\n                <div>\n                    <Inputs.Hidden\n                        name=\"id\"\n                        value={(this.props.scopestate.scope) ? this.props.scopestate.scope.id : 0}\n                    />\n                    <Inputs.FormGroup>\n                        <Inputs.Label\n                            value={this.props.labels.sources}\n                            attributes={{ \"htmlFor\": \"scopeProviderSource\" }}\n                        />\n                        <Inputs.Controls>\n                            <Inputs.Select\n                                value={(hasSource()) ? this.props.scopestate.source.source : 0}\n                                name=\"provider[source]\"\n                                options={sourceOptions}\n                                onChange={onChangeSource}\n                                attributes={{ \"id\": \"scopeProviderSource\" }}\n                            />\n                        </Inputs.Controls>\n                    </Inputs.FormGroup>\n                </div>\n                <div>\n\n                    <Inputs.FormGroup>\n                        <Inputs.Label\n                            value={this.props.labels.providers}\n                            attributes={{ \"htmlFor\": \"scopeProviderId\" }}\n                        />\n                        <Inputs.Controls>\n                            <Inputs.Select\n                                attributes={(!hasSource()) ? { \"disabled\": true, \"id\": \"scopeProviderId\" } : { \"id\": \"scopeProviderId\" }}\n                                value={(hasProvider()) ? this.props.scopestate.provider.id : 0}\n                                name=\"provider[id]\"\n                                groups={providerGroups}\n                                onChange={onChangeProvider}\n                            />\n                        </Inputs.Controls>\n                    </Inputs.FormGroup>\n                </div>\n                <div>\n                    <Inputs.FormGroup>\n                        <Inputs.Label\n                            value={this.props.labels.name}\n                            attributes={{ \"htmlFor\": \"scopeProviderName\" }}\n                        />\n                        <Inputs.Controls>\n                            <Inputs.Text\n                                attributes={{ \"id\": \"scopeProviderName\", \"readOnly\": true, \"maxLength\": 40 }}\n                                name=\"contact[name]\"\n                                value={(hasProvider()) ? this.props.scopestate.provider.contact.name : this.props.labels.notDeclared}\n                            />\n                        </Inputs.Controls>\n                        <Inputs.Hidden\n                            name=\"provider[name]\"\n                            value={(hasProvider()) ? this.props.scopestate.provider.name : this.props.labels.notDeclared}\n                        />\n                    </Inputs.FormGroup>\n                </div>\n                <div>\n                    <Inputs.FormGroup>\n                        <Inputs.Label\n                            value={this.props.labels.address}\n                            attributes={{ \"htmlFor\": \"scopeProviderStreet\" }}\n                        />\n                        <Inputs.Controls>\n                            <Inputs.Text\n                                attributes={{ \"id\": \"scopeProviderStreet\", \"readOnly\": true, \"maxLength\": 70 }}\n                                name=\"contact[street]\"\n                                value={(hasProvider()) ? this.props.scopestate.provider.contact.street + \" \" + this.props.scopestate.provider.contact.streetNumber : this.props.labels.notDeclared}\n                            />\n                        </Inputs.Controls>\n                    </Inputs.FormGroup>\n                </div>\n            </fieldset>\n        )\n    }\n}\n\nSourceSelectView.propTypes = {\n    labels: PropTypes.object.isRequired,\n    scopestate: PropTypes.object.isRequired,\n    changeHandler: PropTypes.func,\n    onChangeSourceHandler: PropTypes.func,\n}\n\nexport default SourceSelectView\n","import React, { Component } from 'react'\nimport PropTypes from 'prop-types'\nimport { deepMerge, makeNestedObj, getFieldList } from '../../lib/utils'\nimport { getEntity } from '../../lib/schema'\nimport SourceView from '../../block/scope/sourcesselectform'\nimport $ from \"jquery\"\n\nclass ScopeView extends Component {\n    constructor(props) {\n        super(props)\n        this.changeHandler = this.changeHandler.bind(this)\n        this.onChangeSourceHandler = this.onChangeSourceHandler.bind(this)\n        this.state = this.props\n    }\n\n    changeHandler(field, value) {\n        let newstate = this.state.scopestate\n        const fieldList = getFieldList(field)\n        if (fieldList.length === 1) {\n            newstate[fieldList.pop()] = value\n        } else {\n            newstate = deepMerge(newstate, makeNestedObj(fieldList, value))\n        }\n        this.setState({ scopestate: newstate });\n    }\n\n    onChangeSourceHandler(field, value) {\n        $.ajax(`${this.props.includeurl}/provider/${value}/`, {\n            method: 'GET'\n        }).done((success) => {\n            this.changeHandler(field, success)\n            getEntity('provider').then((entity) => {\n                this.changeHandler('provider', entity)\n            })\n        }).fail((err) => {\n            if (err.status === 404) {\n                console.log('404 error, ignored')\n            } else {\n                console.log('error', err)\n            }\n        })\n    }\n\n    componentDidMount() {\n        //console.log(\"mounted scopeEdit component\", this.state)\n    }\n\n    componentDidUpdate() {\n        //console.log(\"updated source component\", this.state)\n    }\n\n    render() {\n        return (\n            <div>\n                <SourceView\n                    {...this.props}\n                    changeHandler={this.changeHandler}\n                    onChangeSourceHandler={this.onChangeSourceHandler}\n                />\n            </div>\n        );\n    }\n}\n\nScopeView.propTypes = {\n    includeurl: PropTypes.string.isRequired\n}\n\nexport default ScopeView\n","'use strict';\n\nvar m = require('react-dom');\nif (process.env.NODE_ENV === 'production') {\n  exports.createRoot = m.createRoot;\n  exports.hydrateRoot = m.hydrateRoot;\n} else {\n  var i = m.__SECRET_INTERNALS_DO_NOT_USE_OR_YOU_WILL_BE_FIRED;\n  exports.createRoot = function(c, o) {\n    i.usingClientEn