0, https://github.com/jquery/jquery/pull/557)\n// and CommonJS for browser emulators (trac-13566)\nif ( typeof noGlobal === \"undefined\" ) {\n\twindow.jQuery = window.$ = jQuery;\n}\n\n\n\n\nreturn jQuery;\n} );\n","import moment from 'moment'\n\nconst validate = (data, props) => {\n    const currentTime = new Date()\n    const today = moment(props.today, 'X')\n    today.set('hour', currentTime.getHours())\n    today.set('minute', currentTime.getMinutes())\n    today.set('second', currentTime.getSeconds())\n\n    const selectedDate = moment(props.timestamp, 'X')\n    const yesterday = selectedDate.startOf('day').clone().subtract(1, 'days')\n    const tomorrow = selectedDate.startOf('day').clone().add(1, 'days')\n    \n    let errorList = {\n        id: data.id || data.tempId,\n        itemList: []\n    }\n\n    errorList.itemList.push(validateStartTime(today, tomorrow, selectedDate, data))\n    errorList.itemList.push(validateEndTime(today, yesterday, selectedDate, data))\n    errorList.itemList.push(validateOriginEndTime(today, yesterday, selectedDate, data))\n    errorList.itemList.push(validateType(data))\n    errorList.itemList.push(validateSlotTime(data))\n    \n    errorList.itemList = errorList.itemList.filter(el => el.length);\n    let valid = (0 < errorList.itemList.length) ? false : true\n\n    return {\n        valid,\n        errorList\n    }\n}\n\nfunction validateStartTime(today, tomorrow, selectedDate, data) {\n    let errorList = []\n    const startTime = moment(data.startDate, 'X').startOf('day');\n    const startHour = data.startTime.split(':')[0];\n    const endHour = data.endTime.split(':')[0];\n    const startMinute = data.startTime.split(':')[1];\n    const endMinute = data.endTime.split(':')[1];\n    //const startDateTime = startTime.clone().set({ h: startHour, m: startMinute });\n    const isFuture = (data.kind && 'future' == data.kind);\n    //const isOrigin = (data.kind && 'origin' == data.kind);\n\n    if (! isFuture && selectedDate.unix() > today.unix() && startTime.isAfter(selectedDate.startOf('day'), 'day')) {\n        errorList.push({\n            type: 'startTimeFuture', \n            message: `Das Startdatum der Öffnungszeit muss vor dem ${tomorrow.format('DD.MM.YYYY')} liegen.`\n        })\n    }\n/*\n    if (isOrigin && startTime.isBefore(today.startOf('day'), 'day') && data.__modified) {\n        errorList.push({\n            type: 'startTimeOrigin', \n            message: 'Öffnungszeiten in der Vergangenheit lassen sich nicht bearbeiten '\n            + '(Der Terminanfang am \"'+startDateTime.format('DD.MM.YYYY')+' liegt vor dem heutigen Tag\").'\n        })\n    }\n*/\n\n    if ((startHour == \"00\" && startMinute == \"00\") || (endHour == \"00\" && endMinute == \"00\")) {\n        errorList.push({\n            type: 'startOfDay',\n            message: 'Die Uhrzeit darf nicht \"00:00\" sein.'\n        })\n    }\n    return errorList;\n}\n\nfunction validateEndTime(today, yesterday, selectedDate, data) {\n    var errorList = []\n    const startTime = moment(data.startDate, 'X').startOf('day');\n    const endTime = moment(data.endDate, 'X').startOf('day');\n    const startHour = data.startTime.split(':')[0]\n    const endHour = data.endTime.split(':')[0]\n    const startMinute = data.startTime.split(':')[1]\n    const endMinute = data.endTime.split(':')[1]\n    const dayMinutesStart = (parseInt(startHour) * 60) + parseInt(startMinute);\n    const dayMinutesEnd = (parseInt(endHour) * 60) + parseInt(endMinute);\n    const startTimestamp = startTime.set({ h: startHour, m: startMinute }).unix();\n    const endTimestamp = endTime.clone().set({ h: endHour, m: endMinute }).unix();\n\n    if (dayMinutesEnd <= dayMinutesStart) {\n        errorList.push({\n            type: 'endTime', \n            message: 'Die Uhrzeit \"von\" muss kleiner der Uhrzeit \"bis\" sein.'\n        })\n    } else if (startTimestamp >= endTimestamp) {\n        errorList.push({\n            type: 'endTime', \n            message: 'Das Startdatum muss nach dem Enddatum sein.'\n        })\n    }\n    return errorList;\n}\n\nfunction validateOriginEndTime(today, yesterday, selectedDate, data) {\n    var errorList = []\n    const endTime = moment(data.endDate, 'X').startOf('day');\n    const endHour = data.endTime.split(':')[0]\n    const endMinute = data.endTime.split(':')[1]\n    const endDateTime = endTime.clone().set({ h: endHour, m: endMinute });\n    const endTimestamp = endTime.clone().set({ h: endHour, m: endMinute }).unix();\n    const isOrigin = (data.kind && 'origin' == data.kind)\n\n    if (! isOrigin && selectedDate.unix() > today.unix() && endTime.isBefore(selectedDate.startOf('day'), 'day')) {\n        errorList.push({\n            type: 'endTimeFuture',\n            message: `Das Enddatum der Öffnungszeit muss nach dem ${yesterday.format('DD.MM.YYYY')} liegen.`\n        })\n    }\n\n    if (\n        (! isOrigin && endTimestamp < today.unix()) ||\n        (isOrigin && endTimestamp < today.unix() && data.__modified)\n    ) {\n        errorList.push({\n            type: 'endTimePast', \n            message: 'Öffnungszeiten in der Vergangenheit lassen sich nicht bearbeiten '\n            + '(Die aktuelle Zeit \"'+today.format('DD.MM.YYYY HH:mm')+' Uhr\" liegt nach dem Terminende am \"'+endDateTime.format('DD.MM.YYYY HH:mm')+' Uhr\").'\n        })\n    }\n    return errorList;\n}\n\nfunction validateType(data) {\n    let errorList = []\n    if (!data.type) {\n        errorList.push({\n            type: 'type',\n            message: 'Typ erforderlich'\n        })\n    }\n    return errorList;\n}\n\nfunction validateSlotTime (data) {\n    let errorList = []\n    const startTime = moment(data.startDate, 'X');\n    const startHour = data.startTime.split(':')[0]\n    const endHour = data.endTime.split(':')[0]\n    const startMinute = data.startTime.split(':')[1]\n    const endMinute = data.endTime.split(':')[1]\n    const startTimestamp = startTime.set({ h: startHour, m: startMinute }).unix();\n    const endTimestamp = startTime.set({ h: endHour, m: endMinute }).unix();\n    const slotTime = data.slotTimeInMinutes\n\n    let slotAmount = (endTimestamp - startTimestamp) / 60 % slotTime;\n    if (slotAmount > 0) {\n        errorList.push({\n            type: 'slotCount',\n            message: 'Zeitschlitze müssen sich gleichmäßig in der Öffnungszeit aufteilen lassen.'\n        })\n    }\n    return errorList;\n}\n\nexport default validate;\n","import React from 'react'\nimport PropTypes from 'prop-types'\n\nconst titleAside = (title) => {\n    if (title) {\n        return (<div className=\"left aside\">{title}</div>)\n    }\n}\n\nconst headerRight = (header) => {\n    if (header) {\n        return (<div className=\"right header_right\">{header}</div>)\n    }\n}\n\nconst headerMiddle = (title) => {\n    if (title) {\n        return (<div className=\"middle header_middle\">{title}</div>)\n    }\n}\n\nconst Board = (props) => {\n    const className = `board ${props.className}`\n\n    return (\n        <section className={className}>\n            {props.titleAside || props.headerRight || props.headerMiddle ?\n            <div className=\"board__actions\">\n                {titleAside(props.titleAside)}\n                {headerMiddle(props.title)}\n                {headerRight(props.headerRight)}\n            </div> : null }\n            <div className=\"board__body body\">\n                {props.body}\n            </div>\n            {props.footer ?\n             <div className=\"board__footer footer\">\n                {props.footer}\n            </div> : null }\n        </section>\n    )\n}\n\nBoard.propTypes = {\n    className: PropTypes.string,\n    title: PropTypes.node.isRequired,\n    titleAside: PropTypes.node,\n    headerRight: PropTypes.node,\n    headerMiddle: PropTypes.node,\n    body: PropTypes.node.isRequired,\n    footer: PropTypes.node\n}\n\nexport default Board\n","import React from 'react'\nimport PropTypes from 'prop-types'\n\n\nimport Board from '../layouts/board'\nimport moment from 'moment'\n\nconst renderLink = (conflict, onClick) => {\n    const appointment = conflict.appointments[0]\n    const availability = appointment.availability || {}\n    const startTime = moment(appointment.date, 'X').format('DD.MM.YYYY HH:mm')\n    const slotTime = availability.slotTimeInMinutes || 0\n    const endTime = moment(appointment.date + slotTime * 60 * appointment.slotCount, 'X').format('HH:mm')\n    if (availability.id) {\n        if (moment(appointment.date, 'X').format('HH:mm') === endTime) {\n                return <a href=\"#\" onClick={onClick}><strong>{startTime} Uhr</strong></a>\n        } else {\n              return <a href=\"#\" onClick={onClick}><strong>{startTime} - {endTime} Uhr</strong></a>\n        }\n\n    } else {\n        return <span><strong>{startTime} Uhr</strong></span>\n    }\n}\n\nconst renderConflicts = (conflicts, onSelect) => {\n    if (conflicts.length > 0) {\n        return conflicts.map((conflict, key) => {\n\n            const onClick = ev => {\n                ev.preventDefault()\n                const appointment = conflict.appointments[0]\n                const availability = appointment.availability || {}\n                onSelect(availability.id)\n            }\n\n            return (\n                <div className=\"message message--error message-keep\" role=\"alert\" key={key}>\n                    {renderLink(conflict, onClick)}<br />\n                    {conflict.amendment}\n                </div>\n            )\n        })\n    } else {\n        return (\n            <p>Keine Konflikte</p>\n        )\n    }\n}\n\nconst Conflicts = (props) => {\n    return (\n        <Board className=\"board--spaceless availability-conflicts\"\n            title=\"Konflikte\"\n            body={renderConflicts(props.conflicts, props.onSelect)}\n        />\n    )\n}\n\nConflicts.defaultProps = {\n    conflicts: []\n}\n\nConflicts.propTypes = {\n    conflicts: PropTypes.array,\n    onSelect: PropTypes.func.isRequired\n}\n\nexport default Conflicts\n","import React from 'react'\nimport PropTypes from 'prop-types'\n\nconst marginTabs = {\n    margin: '0px'\n};\n\nconst tabsBar = (props) => {\n    return (\n        <div className=\"tabs js-tabs\">\n            <div className='tabs__tablist' style={marginTabs} aria-label=\"tabnavigation\">\n                {renderTabs(props.tabs, props.onSelect, props.selected)}\n            </div>\n        </div>\n    )\n}\n\nconst renderTabs = (tabs, onSelect, selected) => {\n    if (tabs.length > 0) {\n        return tabs.map((tab, key) => {\n\n            const onClick = ev => {\n                ev.preventDefault()\n                onSelect(tab)\n            }\n\n            return (\n                <button key={key} type=\"button\" className=\"tabs__tab \" role=\"tab\" id=\"\" onClick={onClick} aria-selected={tab.component === selected}>{tab.name}</button>\n            )\n        })\n    }\n}\n\ntabsBar.defaultProps = {\n    tabs: []\n}\n\ntabsBar.propTypes = {\n    tabs: PropTypes.array,\n    onSelect: PropTypes.func.isRequired,\n    selected: PropTypes.string\n}\n\nexport default tabsBar\n","import React from 'react'\nimport PropTypes from 'prop-types'\n\nconst hours = (() => {\n    const hours = []\n    for (let i = 0; i < 24; i = i + 1) {\n        hours.push(i)\n    }\n    return hours\n})()\n\nconst background = () => {\n    return <div className=\"background-level\">\n        {hours.map(i => (\n            <div key={i} className=\"time-level_item\" style={{ left: `${i}em` }}>\n                <div className=\"time-level_item--top\">\n                    <span className=\"text\">{i}:00</span>\n                </div>\n                <div className=\"time-level_item--bottom\">\n                    <span className=\"text\">{i}:00</span>\n                </div>\n            </div>\n         ))}\n    </div>\n}\n\nconst conflicts = (showConflicts, conflicts) => {\n    if ( showConflicts) {\n        return (\n            <div className=\"bars conflict-level\">{conflicts}</div>\n        )\n    }\n}\n\nconst refScroll = (element) => {\n    if (element)\n        element.scrollLeft += 470\n}\n\n\nconst GraphBodyLayout = (props) => {\n    return (\n        <div className=\"grid\">\n            <div className=\"grid__item one-tenth\">\n                <div className=\"availability-timetable_legend\">\n                  { props.showConflicts ? <div className=\"legend__item legend_conflict\">Konflikte</div> : null }\n                    <div className=\"legend__item legend_numberofappointment\">Freie Slots</div>\n                    <div className=\"legend__item legend_appointment\">Termin&shy;kunden</div>\n                    <div className=\"legend__item legend_opening\">Spontan&shy;kunden</div>\n                </div>\n            </div>\n            <div className=\"grid__item nine-tenths\">\n                <div className=\"availability-timetable_container\" ref={refScroll} style={{fontSize: \"70px\"}} >\n                    <div className=\"inner\">\n                        {background()}\n                        {conflicts(props.showConflicts, props.conflicts)}\n                        <div className=\"bars numberofappointment-level\">{props.numberOfAppointments}</div>\n                        <div className=\"bars appointment-level\">{props.appointments}</div>\n                        <div className=\"bars opening-level\">{props.openings}</div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    )\n}\n\nGraphBodyLayout.propTypes = {\n    conflicts: PropTypes.node,\n    numberOfAppointments: PropTypes.node,\n    appointments: PropTypes.node,\n    openings: PropTypes.node,\n    showConflicts: PropTypes.bool\n}\n\nexport default GraphBodyLayout\n","import React from 'react'\n\nconst calendarNavigation = (links) => {\n\n    return (\n        <div className=\"calendar-navigation\">\n            {(links.previousDay >= links.sameDay) &&  \n                    <a href={links.previousDay} title=\"Tag zurück\" className=\"icon prev\"><i className=\"fas fa-caret-square-left\" aria-hidden=\"true\"></i> <span className=\"aural\">Tag zurück</span></a>\n            }\n            {(links.previousDay >= links.sameDay) ||  \n                    <span title=\"Tag zurück nicht möglich\" className=\"icon prev inactive\"><i className=\"fas fa-caret-square-left color-text-disabled\"></i></span>\n            }\n            &nbsp;<a href={links.sameDay} className=\"today\">Heute</a>&nbsp;\n            <a href={links.nextDay} title=\"Tag vor\" className=\"icon next\"><i className=\"fas fa-caret-square-right\" aria-hidden=\"true\"></i> <span className=\"aural\">Tag vor</span></a>\n        </div>\n        \n    )\n}\n\nexport default calendarNavigation\n","import PropTypes from 'prop-types'\nimport propTypeAvailability from \"./propTypeAvailability\"\n\nconst propsTypeConflict = PropTypes.shape({\n    type: PropTypes.oneOf(['conflict']),\n    amendment: PropTypes.string,\n    appointments: PropTypes.arrayOf(\n        PropTypes.shape({\n            availability: propTypeAvailability,\n            date: PropTypes.oneOfType([\n                PropTypes.string,\n                PropTypes.number\n            ]) \n        })\n    ),\n    endTime: PropTypes.string\n})\n\n\nexport default propsTypeConflict","import PropTypes from 'prop-types'\n\nconst propsTypeAvailability = PropTypes.shape({\n    type: PropTypes.oneOf(['appointment', 'openinghours']),\n    description: PropTypes.string,\n    startTime: PropTypes.string,\n    endTime: PropTypes.string\n})\n\n\nexport default propsTypeAvailability","import $ from 'jquery'\n\nclass ExceptionHandler {\n\n    constructor(element, options) {\n        this.$main = $(element)\n        this.message = options.message;\n        this.parent = options.parent || this.$main;\n        this.code = options.code;\n        this.callback = options.callback || this.closeException;\n        this.bindEvents();\n        this.render();\n    }\n\n    render() {\n        var $message = $(this.message).filter('.exception');\n        if ($message.length == 0) {\n            $message = $(this.message).find('.exception');\n        }\n\n        this.$messageElement = $($message.get(0).outerHTML);\n\n        this.$main.find('.dialog, .exception').remove();\n        this.$main.find('.body').first().prepend(this.$messageElement);\n\n        var $buttons = this.$messageElement.find('.btn');\n        if ($buttons.length == 0) {\n            $buttons = $('<button class=\"button button--diamond btn button-cancel close right\" title=\"Schließen\"><i class=\"fas fa-times\" aria-hidden=\"true\"></i> <span class=\"aural\">Schließen</span></button>');\n            this.$messageElement.find('.header').append($buttons);\n        }\n        $buttons.on('click', (ev) => {\n            ev.preventDefault();\n            ev.stopPropagation();\n            var callback = $(ev.target).data('callback');\n            if (this.parent[callback]) {\n                this.callback = this.parent[callback];\n            }\n            this.callback(ev);\n        })\n        /*setTimeout(() => {\n            this.closeException();\n        },8000)\n        */\n    }\n\n    closeException() {\n        if (this.$messageElement) {\n            this.$messageElement.remove();\n        }\n    }\n\n    bindEvents() {\n    }\n}\n\nexport default ExceptionHandler\n","\nimport $ from 'jquery'\nimport moment from 'moment'\nimport Baseview from './baseview';\nimport settings from '../settings';\n\nexport const timeToFloat = (time) => {\n    const momentTime = moment(time, 'HH:mm:ss')\n\n    return momentTime.hours() + (momentTime.minutes() / 60)\n}\n\nexport const timestampToFloat = timestamp => {\n    const momentTime = moment(timestamp, 'X')\n\n    return momentTime.hours() + (momentTime.minutes() / 60)\n}\n\nexport const range = (start, end, step = 1) => {\n    const result = []\n    for (let i = start; i <= end; i += step) {\n        result.push(i)\n    }\n\n    return result\n}\n\nexport const loopWithCallback = (array, callback) => {\n    for (var i = 0; i < array.length; i++) {\n        let result = callback(array[i])\n        if (result) { return result }\n    }\n}\n\nexport const deepGet = (obj, path = []) => path.reduce((carry, current) => carry ? carry[current] : undefined, obj)\n\nexport const deepMerge = (target, ...sources) => {\n    if (!sources.length) return target;\n    target = toObject(target)\n    const source = toObject(sources.shift())\n\n    for (const key in source) {\n        if (isObject(source[key])) {\n            if (!target[key]) Object.assign(target, { [key]: {} });\n            deepMerge(target[key], source[key]);\n        } else {\n            Object.assign(target, { [key]: source[key] });\n        }\n    }\n\n\n    return deepMerge(target, ...sources);\n}\n\nexport const isObject = (item) => {\n    return (item && typeof item === 'object' && !Array.isArray(item));\n}\n\nexport const toObject = (arr) => {\n    let newObj = arr;\n    if (!isObject(newObj)) {\n        newObj = Object.assign({}, arr)\n    }\n    return newObj;\n}\n\nexport const getFieldList = (field) => {\n    let fieldList = [];\n    let match;\n    let reg = RegExp('([^[]+)', 'g');\n    while ((match = reg.exec(field))) {\n        fieldList.push(match.pop().replace(']', ''))\n    }\n    return fieldList;\n}\n\nexport const makeNestedObj = (arr, value) => {\n    const reducer = (acc, item) => ({ [item]: acc });\n    return arr.reduceRight(reducer, value);\n}\n\nconst attributesToArray = attributes => Array.prototype.slice.call(attributes, 0)\n\nexport const toArray = (data) => {\n    return Object.keys(data).map(key => ({ [key]: data[key] }));\n}\n\nexport const inArray = (value,arr) => {\n    var status = false;\n    for(var i=0; i<arr.length; i++){\n      var name = arr[i];\n      if(name == value){\n        status = true;\n        break;\n      }\n    }\n    return status;\n  }\n\nexport const getDataAttributes = (element) => {\n    const attributes = attributesToArray(element.attributes)\n    const dataRegex = /^data-/i\n\n    return attributes\n        .filter(attribute => (dataRegex.test(attribute.nodeName)))\n        .map(attribute => [\n            attribute.name.replace(dataRegex, ''),\n            attribute.value]\n        )\n        .reduce((carry, [key, value]) => {\n            carry[key] = tryJson(value)\n            return carry\n        }, {})\n}\n\nexport const tryJson = (input) => {\n    try {\n        return JSON.parse(input)\n    } catch (e) {\n        return input\n    }\n}\n\nconst lightboxHtml = '<div class=\"lightbox\"><div class=\"lightbox__content\" role=\"dialog\" aria-modal=\"true\"></div></div>'\n\nexport const lightbox = (parentElement, onBackgroundClick) => {\n    const lightboxElement = $(lightboxHtml)\n\n    if (!parentElement) {\n        parentElement = $('body')\n        lightboxElement.addClass('fixed')\n    }\n\n    const destroyLightbox = () => {\n        lightboxElement.off()\n        lightboxElement.remove()\n    }\n\n    const lightboxContentElement = lightboxElement.find('.lightbox__content');\n\n    lightboxElement.on('click', (ev) => {\n        //console.log('background click', ev);\n        ev.stopPropagation()\n        ev.preventDefault()\n        destroyLightbox()\n        onBackgroundClick()\n    }).on('click', '.lightbox__content', (ev) => {\n        ev.stopPropagation();\n    })\n\n\n    if ($(parentElement).find('.lightbox').length) {\n        $(parentElement).find('.lightbox').remove();\n    }\n    $(parentElement).append(lightboxElement)\n\n    return {\n        lightboxContentElement,\n        destroyLightbox\n    }\n}\n\nexport const noOp = () => { }\n\nexport const stopEvent = (ev) => {\n    if (ev) {\n        ev.preventDefault();\n        ev.stopPropagation();\n    }\n}\n\nexport const getUrlParameters = () => {\n    return document.location.search.replace(/^\\?/, \"\")\n        .split(\"&\")\n        .reduce((carry, current) => {\n            const [key, value] = current.split('=')\n            if (key) {\n                return Object.assign({}, carry, { [key]: value })\n            } else {\n                return carry\n            }\n        }, {})\n}\n\nexport const forceHttps = () => {\n    var forceCallback = () => {\n        document.location.href = \"https://\" + document.location.href.substring(document.location.protocol.length, document.location.href.length);\n    }\n    if (document.location.protocol !== \"https:\") {\n        Baseview.loadCallStatic(`${settings.includeUrl}/dialog/?template=force_https`).then((response) => {\n            Baseview.loadDialogStatic(response,\n                forceCallback,\n                forceCallback,\n                Baseview,\n                true\n            );\n        });\n    }\n\n}\n\nexport const showSpinner = ($container = null) => {\n    var loaderContainer = $('#main-content');\n    if ($container !== null) {\n        loaderContainer = $container.find('.body').first();\n    }\n    loaderContainer.prepend('<div class=\"loader\" aria-hidden=\"true\"><div class=\"spinner\"></div></div>');\n}\n\nexport const hideSpinner = ($container = null) => {\n    var loaderContainer = $('#main-content');\n    if ($container !== null) {\n        loaderContainer = $container.find('.body').first();\n        loaderContainer.find('.loader').detach();\n    } else {\n        loaderContainer.find('.loader').first().detach();\n    }\n\n}\n","import React from 'react'\n\nimport propTypeConflict from '../../../../lib/propTypeConflict'\nimport { timestampToFloat } from '../../../../lib/utils'\nimport moment from 'moment'\n\nconst Conflict = props => {\n    const { data } = props\n\n    const appointment = data.appointments[0]\n    const availability = appointment.availability || {}\n    const slotTime = availability.slotTimeInMinutes || 0\n\n    const timeItemStart = timestampToFloat(appointment.date)\n    const timeItemEnd = timestampToFloat(appointment.date + slotTime * 60 * appointment.slotCount)\n    const timeItemLength = timeItemEnd - timeItemStart\n\n    const firstAppointmentTime = moment(data.appointments[0].date, 'X')\n\n    const title = `${data.amendment} ${firstAppointmentTime.format('HH:mm')}`\n\n    const style = {\n        left: `${timeItemStart}em`,\n        width: `${timeItemLength}em`\n    }\n\n    return (\n        <div className=\"item-bar\" {...{ title, style }} >\n            <span className=\"item-bar_inner\">⚡</span>\n        </div>\n    )\n}\n\nConflict.propTypes = {\n    data: propTypeConflict\n}\n\nexport default Conflict\n","import React from 'react'\nimport PropTypes from 'prop-types'\nimport moment from 'moment'\n\nimport propTypeAvailability from '../../../../lib/propTypeAvailability'\nimport { timeToFloat } from '../../../../lib/utils'\n\nconst Appointment = props => {\n    const { data, maxWorkstationCount, onSelect } = props\n    const heightEm = maxWorkstationCount > 0\n                   ? data.workstationCount.intern * 0.8 / maxWorkstationCount\n                   : 0\n\n    const timeItemStart = timeToFloat(data.startTime)\n    const timeItemEnd = timeToFloat(data.endTime)\n    const timeItemLength = timeItemEnd - timeItemStart\n\n    const startTime = moment(data.startTime, 'hh:mm:ss').format('HH:mm');\n    const endTime = moment(data.endTime, 'hh:mm:ss').format('HH:mm');\n\n    const description = (data.description) ? `${data.description}, ` : ``;\n    const title = `${description}${startTime} - ${endTime} - Insgesamt:${data.workstationCount.intern} / Callcenter: ${data.workstationCount.callcenter} / Internet: ${data.workstationCount.public}`\n\n    const style = {\n        height: `${heightEm}em`,\n        left: `${timeItemStart}em`,\n        width: `${timeItemLength}em`\n    }\n\n    const onClick = ev => {\n        ev.preventDefault()\n        onSelect(data)\n    }\n\n    return (\n        <a href=\"#\" className=\"item-bar\" {...{ title, style, onClick }}>\n            <span className=\"item-bar_inner\"><i className=\"fas fa-user-alt\" aria-hidden=\"true\"></i> { data.workstationCount.intern }</span>\n        </a>\n    )\n}\n\nAppointment.propTypes = {\n    data: propTypeAvailability,\n    maxWorkstationCount: PropTypes.number,\n    onSelect: PropTypes.func.isRequired\n}\n\nexport default Appointment\n","import React from 'react'\nimport PropTypes from 'prop-types'\nimport moment from 'moment'\nimport propTypeAvailability from '../../../../lib/propTypeAvailability'\nimport { timeToFloat } from '../../../../lib/utils'\n\nconst NumberOfAppointments = props => {\n    const { data, maxWorkstationCount } = props\n    const startTime = moment(data.startTime, 'hh:mm:ss').format('HH:mm');\n    const endTime = moment(data.endTime, 'hh:mm:ss').format('HH:mm');\n    const title = (data.description) ? `${data.description}, ${startTime} - ${endTime}` : `${startTime} - ${endTime}`\n                   \n    const timeItemStart = timeToFloat(data.startTime)\n    const timeItemEnd = timeToFloat(data.endTime)\n    const timeItemLength = timeItemEnd - timeItemStart\n\n\n    const busy = data.busySlots\n    const max = data.maxSlots\n\n    const heightEm = maxWorkstationCount > 0\n        ? data.workstationCount.intern * 1.6 / maxWorkstationCount\n        : 0\n\n    const busyBarStyle = {\n        height: `${Math.round(100 * busy/max, 2)}%`\n    }\n\n    const style = {\n        height: `${heightEm}em`,\n        left: `${timeItemStart}em`,\n        width: `${timeItemLength}em`\n    }\n    return (\n        <div className=\"item-bar\" {... { title, style }}>\n            <div style={busyBarStyle} className=\"busy-bar\"></div>\n            <span className=\"item-bar_inner\">{busy}/{max}</span>\n        </div>\n    )\n}\n\nNumberOfAppointments.propTypes = {\n    data: propTypeAvailability,\n    selectedAvailability: propTypeAvailability,\n    maxWorkstationCount: PropTypes.number\n}\n\nexport default NumberOfAppointments\n","import React from 'react'\nimport PropTypes from 'prop-types'\nimport moment from 'moment'\n\nimport propTypeAvailability from '../../../../lib/propTypeAvailability'\nimport { timeToFloat } from '../../../../lib/utils'\n\nconst Opening = props => {\n    const { data, onSelect } = props\n    const startTime = moment(data.startTime, 'hh:mm:ss').format('HH:mm');\n    const endTime = moment(data.endTime, 'hh:mm:ss').format('HH:mm');\n    const description = (data.description) ? `${data.description}, ` : ``;\n    const title = `${description}${startTime} - ${endTime}`\n\n    const timeItemStart = timeToFloat(data.startTime)\n    const timeItemEnd = timeToFloat(data.endTime)\n    const timeItemLength = timeItemEnd - timeItemStart\n\n    const style = {\n        left: `${timeItemStart}em`,\n        width: `${timeItemLength}em`\n    }\n\n    const onClick = ev => {\n        ev.preventDefault()\n        onSelect(data)\n    }\n\n    return (\n        <a href=\"#\" className=\"item-bar\" {... { title, style, onClick }}>\n            <span className=\"item-bar_inner\"></span>\n        </a>\n    )\n}\n\nOpening.propTypes = {\n    data: propTypeAvailability,\n    onSelect: PropTypes.func.isRequired\n}\n\nexport default Opening\n","\nimport React from 'react'\nimport ConflictTimeBar from '../widgets/timeBars/conflict'\nimport AppointmentTimeBar from '../widgets/timeBars/appointment'\nimport NumberOfAppointmentsTimeBar from '../widgets/timeBars/numberOfAppointments'\nimport OpeningTimebar from '../widgets/timeBars/opening'\n\nexport const headerMiddle = () => {\n    return (\n        <span className=\"middle\"></span>\n    )\n}\n\nexport const headerRight = (links) => {\n    return (\n        <span className=\"right\">\n            <a href={links.monthView}>zurück zur Monatsansicht</a>\n        </span>\n    )\n}\n\nexport const renderConflicts = (conflicts) => {return conflicts\n    .map((data, key) => <ConflictTimeBar key={key} {...{ key, data }} />)}\n\nexport const renderNumberOfAppointments = (items, maxWorkstationCount) => {return items\n    .filter(item => item.type === 'appointment')\n    .map((data, key) => <NumberOfAppointmentsTimeBar key={key} {...{ key, data, maxWorkstationCount }} />)}\n\n\nexport const renderAppointments = (items, maxWorkstationCount, onSelect) => {return items\n    .filter(item => item.type === 'appointment')\n    .map((data, key) => <AppointmentTimeBar key={key} {...{ key, data, maxWorkstationCount, onSelect }} />)}\n\n\nexport const renderOpenings = (items, onSelect) => {return items\n    .filter(item => item.type === \"openinghours\")\n    .map((data, key) => <OpeningTimebar key={key} {...{ key, data, onSelect }} />)}\n\nexport const renderFooter = () => {return <small>Zum Bearbeiten einer Öffnungszeit, bitte auf den entsprechenden blauen oder grünen Zeitstrahl klicken.</small>}","import React from 'react'\nimport PropTypes from 'prop-types'\n\nimport moment from 'moment/min/moment-with-locales';\nmoment.locale('de')\n\nimport Board from '../layouts/board'\nimport GraphBodyLayout from '../layouts/graphBody'\nimport calendarNavigation from '../widgets/calendarNavigation'\nimport * as constants from './index.js'\n\nconst GraphView = (props) => {\n    const { onSelect, timestamp } = props;\n    const titleTime = moment(timestamp, 'X').format('dddd, DD.MM.YYYY')\n    const graphBody = <GraphBodyLayout\n        showConflicts={props.conflicts.length > 0}\n        conflicts={constants.renderConflicts(props.conflicts)}\n        appointments={constants.renderAppointments(props.availabilityList, props.maxWorkstationCount, onSelect)}\n        numberOfAppointments={constants.renderNumberOfAppointments(props.availabilityList, props.maxWorkstationCount)}\n        openings={constants.renderOpenings(props.availabilityList, onSelect)} \n    />\n    return (\n        <Board className=\"board--light availability-timetable\"\n            title={titleTime}\n            titleAside={calendarNavigation(props.links)}\n            headerRight={constants.headerRight(props.links, props.onNewAvailability)}\n            headerMiddle={constants.headerMiddle()}\n            body={graphBody}\n            footer={constants.renderFooter()}\n        />\n    )\n}\n\nGraphView.defaultProps = {\n    onNewAvailability: () => { },\n    availabilityList: [],\n    conflicts: []\n}\n\nGraphView.propTypes = {\n    timestamp: PropTypes.number,\n    links: PropTypes.object,\n    onNewAvailability: PropTypes.func,\n    conflicts: PropTypes.array,\n    availabilityList: PropTypes.array,\n    maxWorkstationCount: PropTypes.number,\n    onSelect: PropTypes.func.isRequired\n}\n\nexport default GraphView\n\n","import moment from 'moment'\n\nexport const getStateFromProps = props => {\n    return {\n        availabilitylistslices: writeSlotCalculationIntoAvailability(\n            props.availabilitylist, \n            props.maxslots, \n            props.busyslots\n        ),\n        availabilitylist: props.availabilitylist,\n        conflicts: props.conflicts,\n        today: props.today,\n        busyslots: props.busyslots\n    }\n}\n\nexport const writeSlotCalculationIntoAvailability = (availabilitylist, maxslots, busyslots) => {\n    return availabilitylist.map(item => {\n        let itemId = item.id ? item.id : item.tempId;\n        return Object.assign({}, item, {\n            maxSlots: maxslots[itemId] || 0,\n            busySlots: busyslots[itemId] || 0\n        })\n    })\n}\n\nexport const mergeAvailabilityListIntoState = (state, list) => list.reduce(updateAvailabilityInState, state)\n\n/**\n * Compare two availabilityList if they are the same using ID\n */\nconst equalIds = (a, b) => {\n    return (a.id && b.id && a.id === b.id) || (a.tempId && b.tempId && a.tempId === b.tempId)\n}\n\nexport const findAvailabilityInStateByKind = (state, kind) => {\n    return state.availabilitylist.find(availabilty => availabilty.kind == kind);\n}\n\nexport const updateAvailabilityInState = (state, newAvailability) => {\n    let updated = false\n\n    const newState = Object.assign({}, state, {\n        availabilitylist: state.availabilitylist.map(availability => {\n            if (equalIds(availability, newAvailability)) {\n                updated = true\n                return newAvailability\n            } else {\n                return availability\n            }\n        })\n    })\n\n    if (!updated) {\n        newState.availabilitylist.push(newAvailability)\n    }\n\n    newState.stateChanged = true\n\n    return newState\n}\n\nexport const deleteAvailabilityInState = (state, deleteAvailability) => {\n    return Object.assign({}, state, {\n        stateChanged: true,\n        availabilitylist: state.availabilitylist.filter(availabilty => availabilty.id !== deleteAvailability.id)\n    })\n}\n\nexport const formatTimestampDate = timestamp => moment(timestamp, 'X').format('YYYY-MM-DD')\n\nexport const getInitialState = (props) => Object.assign({}, {\n    availabilitylist: [],\n    selectedAvailability: null,\n    formTitle: null,\n    lastSave: null,\n    stateChanged: false,\n    selectedTab: 'table',\n}, getStateFromProps(props))\n\nexport const getNewAvailability = (timestamp, tempId, scope) => {\n    const now = moment(timestamp, 'X')\n    const weekday = [\n        'monday',\n        'tuesday',\n        'wednesday',\n        'thursday',\n        'friday',\n        'saturday',\n        'sunday'\n    ][now.isoWeekday() - 1]\n\n    const newAvailability = {\n        id: null,\n        tempId,\n        scope: Object.assign({}, scope),\n        description: 'Neue Öffnungszeit',\n        startDate: timestamp,\n        endDate: timestamp,\n        startTime: '07:00:00',\n        endTime: '20:00:00',\n        bookable: {\n            startInDays: \"0\",\n            endInDays: \"0\"\n        },\n        multipleSlotsAllowed: 1,\n        slotTimeInMinutes: 10,\n        weekday: {\n            [weekday]: 1\n        },\n        workstationCount: {\n            intern: 0,\n            callcenter: 0,\n            'public': 0\n        },\n        repeat: {\n            afterWeeks: 0,\n            weekOfMonth: 0\n        },\n        type: null,\n        kind: \"new\"\n    }\n\n    return newAvailability\n}\n\nexport const availabilityTypes = [\n    { value: \"0\", name: \"--Bitte wählen--\" },\n    { value: \"openinghours\", name: \"Spontankunden\" },\n    { value: \"appointment\", name: \"Terminkunden\" },\n]\n\nexport const weekDayList=[\n    { value: \"monday\", label: \"Montag\" },\n    { value: \"tuesday\", label: \"Dienstag\" },\n    { value: \"wednesday\", label: \"Mittwoch\" },\n    { value: \"thursday\", label: \"Donnerstag\" },\n    { value: \"friday\", label: \"Freitag\" },\n    { value: \"saturday\", label: \"Samstag\" },\n    { value: \"sunday\", label: \"Sonntag\" }\n]\n\nexport const availabilitySeries=[\n    { value: \"0\", name: \"einmaliger Termin\" },\n    { value: \"-1\", name: \"jede Woche\" },\n    { value: \"-2\", name: \"alle 2 Wochen\" },\n    { value: \"-3\", name: \"alle 3 Wochen\" },\n    { value: \"1\", name: \"jede 1. Woche im Monat\" },\n    { value: \"2\", name: \"jede 2. Woche im Monat\" },\n    { value: \"3\", name: \"jede 3. Woche im Monat\" },\n    { value: \"4\", name: \"jede 4. Woche im Monat\" },\n    { value: \"5\", name: \"jede letzte Woche im Monat\" }\n]\n\nexport const repeat = repeat => {\n    if (repeat.afterWeeks > 0) {\n        return -repeat.afterWeeks\n    } else if (repeat.weekOfMonth > 0) {\n        return repeat.weekOfMonth\n    } else {\n        return 0\n    }\n}\n\nexport const filterEmptyAvailability = (availability) => {\n    return availability.startDate != null && availability.endDate != null\n}\n\nexport const cleanupAvailabilityForSave = availability => {\n    const newAvailability = Object.assign({}, availability)\n\n    if (newAvailability.busySlots) {\n        delete newAvailability.busySlots;\n    }\n\n    if (newAvailability.maxSlots) {\n        delete newAvailability.maxSlots;\n    }\n\n    if (newAvailability.__modified) {\n        delete newAvailability.__modified;\n    }\n\n    if (newAvailability.tempId) {\n        delete newAvailability.tempId;\n    }\n\n    if (newAvailability.kind) {\n        delete newAvailability.kind;\n    }\n\n    return newAvailability;\n}\n\nexport const getDataValuesFromForm = (form, scope) => {\n    return Object.assign({}, getFirstLevelValues(form), {\n        bookable: {\n            startInDays: form.open_from === \"\" ? scope.preferences.appointment.startInDaysDefault : form.open_from,\n            endInDays: form.open_to === \"\" ? scope.preferences.appointment.endInDaysDefault : form.open_to\n        },\n        workstationCount: {\n            intern: form.workstationCount_intern,\n            callcenter: form.workstationCount_callcenter,\n            \"public\": form.workstationCount_public\n        },\n        weekday: form.weekday.reduce((carry, current) => {\n            return Object.assign({}, carry, { [current]: 1 })\n        }, {}),\n        repeat: {\n            weekOfMonth: form.repeat > 0 ? form.repeat : 0,\n            afterWeeks: form.repeat < 0 ? -form.repeat : 0\n        }\n    })\n}\n\nexport const cleanupFormData = data => {\n    let internCount = parseInt(data.workstationCount_intern, 10);\n    let callcenterCount = parseInt(data.workstationCount_callcenter, 10);\n    callcenterCount = (callcenterCount > internCount) ? internCount : callcenterCount;\n    let publicCount = parseInt(data.workstationCount_public, 10);\n    publicCount = (publicCount > internCount) ? internCount : publicCount;\n    return Object.assign({}, data, {\n        workstationCount_callcenter: callcenterCount,\n        workstationCount_public: publicCount,\n        open_from: (data.open_from === \"0\" || data.open_from === data.openFromDefault) ? \"\" : data.open_from,\n        open_to: (data.open_to === \"0\" || data.open_to === data.openToDefault) ? \"\" : data.open_to\n    })\n}\n\nexport const getFirstLevelValues = data => {\n    const {\n        __modified,\n        scope,\n        description,\n        startTime,\n        endTime,\n        startDate,\n        endDate,\n        multipleSlotsAllowed,\n        id,\n        tempId,\n        type,\n        slotTimeInMinutes,\n        kind\n    } = data\n\n    return {\n        __modified,\n        scope,\n        description,\n        startTime,\n        endTime,\n        startDate,\n        endDate,\n        multipleSlotsAllowed,\n        id,\n        tempId,\n        type,\n        slotTimeInMinutes,\n        kind\n    }\n}\n\nexport const getFormValuesFromData = data => {\n    const workstations = Object.assign({}, data.workstationCount)\n\n    if (parseInt(workstations.callcenter, 10) > parseInt(workstations.intern, 10)) {\n        workstations.callcenter = workstations.intern\n    }\n\n    if (parseInt(workstations.public, 10) > parseInt(workstations.intern, 10)) {\n        workstations.public = workstations.intern\n    }\n\n    const openFrom = data.bookable.startInDays\n    const openFromDefault = data.scope.preferences.appointment.startInDaysDefault\n    const openTo = data.bookable.endInDays\n    const openToDefault = data.scope.preferences.appointment.endInDaysDefault\n    const repeatSeries = repeat(data.repeat);\n\n    return cleanupFormData(Object.assign({}, getFirstLevelValues(data), {\n        open_from: openFrom,\n        open_to: openTo,\n        openFromDefault,\n        openToDefault,\n        repeat: repeatSeries,\n        workstationCount_intern: workstations.intern,\n        workstationCount_callcenter: workstations.callcenter,\n        workstationCount_public: workstations.public,\n        weekday: Object.keys(data.weekday).filter(key => parseInt(data.weekday[key], 10) > 0)\n    }))\n}\n\nexport const accordionTitle = (data) => {\n    const startDate = moment(data.startDate, 'X').format('DD.MM.YYYY');\n    const endDate = moment(data.endDate, 'X').format('DD.MM.YYYY');\n    const startTime = moment(data.startTime, 'h:mm:ss').format('HH:mm');\n    const endTime = moment(data.endTime, 'h:mm:ss').format('HH:mm');\n    const availabilityType = availabilityTypes.find(element => element.value == data.type);\n    const availabilityWeekDayList = Object.keys(data.weekday).filter(key => parseInt(data.weekday[key], 10) > 0)\n    const availabilityWeekDay = weekDayList.filter(element => availabilityWeekDayList.includes(element.value)\n    ).map(item => item.label).join(', ')\n    let description = (data.description) ? `: ${data.description}` : \"\";\n    let type = (availabilityType && availabilityWeekDay) ? ` Typ: ${availabilityType.name}, Wochentag: ${availabilityWeekDay}` : \"\";\n    return `Zeitraum: ${startDate} bis ${endDate}, Uhrzeit: von ${startTime} bis ${endTime}, ${type}${description}`\n        \n}","import React from 'react'\nimport PropTypes from 'prop-types'\nimport moment from 'moment/min/moment-with-locales';\nimport {weekDayList, availabilitySeries, availabilityTypes, repeat} from '../helpers'\nmoment.locale('de')\n\nconst TableBodyLayout = (props) => {\n    const { onDelete, onSelect, onAbort, availabilityList, data } = props;\n    return (\n        <div className=\"table-responsive-wrapper\"> \n            <table className=\"table--base\">\n                <thead>\n                    <tr>\n                        <th></th>\n                        <th>Wochentage</th>\n                        <th>Serie</th>\n                        <th>Von</th>\n                        <th>Bis</th>\n                        <th>Uhrzeit</th>\n                        <th>Typ</th>\n                        <th>Zeitschlitz</th>\n                        <th>Arbeitsplätze</th>\n                        <th>Buchung</th>\n                        <th>Anmerkung</th>\n                    </tr>\n                </thead>\n                <tbody>\n                {renderTable(onDelete, onSelect, onAbort, availabilityList, data)}\n                </tbody>\n            </table>\n        </div>\n    )\n}\n\n/* eslint-disable complexity */\nconst renderTable = (onDelete, onSelect, onAbort, availabilityList, data) => {\n    if (availabilityList.length > 0) {\n        return availabilityList.map((availability, key) => {\n\n            const startDate = moment(availability.startDate, 'X').format('DD.MM.YYYY');\n            const endDate = moment(availability.endDate, 'X').format('DD.MM.YYYY');\n            const startTime = moment(availability.startTime, 'h:mm:ss').format('HH:mm');\n            const endTime = moment(availability.endTime, 'h:mm:ss').format('HH:mm');\n\n            const titleEdit = `Bearbeiten von ${availability.id} (${startDate} - ${endDate})`\n            const titleDelete = `Löschen von ${availability.id} (${startDate} - ${endDate})`\n            const titleAbort = `Die aktuelle Beabeitung wird zurückgesetzt.`\n            const titleDisabled = `Diese Aktion ist während einer aktuellen Bearbeitung nicht möglich.`\n\n            if (! availability.id && ! availability.tempId) {\n                availability.tempId = `spontaneous_ID_${key}`\n            }\n\n            const onClickEdit = ev => {\n                ev.preventDefault()\n                onSelect(availability)\n            }\n\n            const onClickDelete = ev => {\n                ev.preventDefault()\n                onDelete(availability)\n            }\n\n            const onClickAbort = ev => {\n                ev.preventDefault()\n                onAbort()\n            }\n\n            const availabilityWeekDayList = Object.keys(availability.weekday).\n                filter(key => parseInt(availability.weekday[key], 10) > 0)\n            \n            const availabilityWeekDay = weekDayList.\n                filter(element => availabilityWeekDayList.includes(element.value)).map(item => item.label).join(', ')\n\n            const availabilityRepeat = availabilitySeries.\n                find(element => element.value == repeat(availability.repeat)).name\n\n            const availabilityType = availabilityTypes.\n                find(element => element.value == availability.type)\n\n            const disabled = (\n                (availability.id && availability.__modified) || \n                (availability.tempId && availability.__modified)\n            ); \n\n            const isSelected = (data && (\n                (data.id && availability.id == data.id) || \n                (data.tempId && availability.tempId == data.tempId))\n            );\n\n            return (\n                <tr key={key} style={isSelected ? {backgroundColor: '#f9f9f9'} : null}>\n                    <td className=\"center\" style={{\"whiteSpace\": \"nowrap\"}}>\n                        <span style={{ marginRight: \"5px\" }}>\n                            <a href=\"#\" className=\"icon\" aria-label=\"Bearbeiten\" title={titleEdit} onClick={onClickEdit}>\n                                <i className=\"fas fa-pencil-alt\" aria-hidden=\"true\"></i>\n                            </a>\n                        </span>\n                        <span>\n                            { disabled ?\n                            <i className=\"far fa-trash-alt\" title={titleDisabled}></i> : \n                            <a href=\"#\" className=\"icon\" title={titleDelete} aria-label={titleDelete} onClick={onClickDelete}>\n                                <i className=\"far fa-trash-alt\" aria-hidden=\"true\"></i>\n                            </a>\n                            }\n                        </span>\n                        { disabled ?\n                        <span style={{ marginLeft: \"5px\" }}>\n                            <a href=\"#\" className=\"icon\" title={titleAbort} aria-label=\"abbrechen\" onClick={onClickAbort}>\n                                <i className=\"fas fa-ban\" aria-hidden=\"true\"></i>\n                            </a>\n                        </span>\n                         : null\n                        }\n                    </td>\n                    <td>\n                        {availabilityWeekDay}\n                    </td>\n                    <td>\n                        {availabilityRepeat}\n                    </td>\n                    <td>\n                        {startDate}\n                    </td>\n                    <td>\n                        {endDate}\n                    </td>\n                    <td>\n                        {startTime} - {endTime}\n                    </td>\n                    <td>\n                        {availabilityType && availabilityType.name ? availabilityType.name : \"\"}\n                    </td>\n                    <td>\n                        {availability.slotTimeInMinutes}min\n                    </td>\n                    <td>\n                        {availability.workstationCount.intern}/{availability.workstationCount.callcenter}/{availability.workstationCount.public}\n                    </td>\n                    <td>\n                        {availability.bookable.startInDays}-{availability.bookable.endInDays}\n                    </td>\n                    <td>\n                        {availability.description ? availability.description : '-'}\n                    </td>\n                </tr>\n            )\n        })\n    }\n}\n\nTableBodyLayout.propTypes = {\n    availabilityList: PropTypes.array,\n    data: PropTypes.object,\n    onSelect: PropTypes.func.isRequired,\n    onDelete: PropTypes.func.isRequired,\n    onAbort: PropTypes.func.isRequired\n}\n\nexport default TableBodyLayout\n","import React from 'react'\nimport PropTypes from 'prop-types'\n\nimport moment from 'moment/min/moment-with-locales';\nmoment.locale('de')\n\nimport Board from '../layouts/board'\nimport TableBodyLayout from '../layouts/tableBody'\nimport calendarNavigation from '../widgets/calendarNavigation'\nimport * as constants from './index.js'\n\nconst TableView = (props) => {\n    const { onDelete, onSelect, onAbort, timestamp, availabilityList, data } = props;\n    const titleTime = moment(timestamp, 'X').format('dddd, DD.MM.YYYY')\n    const TableBody = <TableBodyLayout\n        availabilityList={availabilityList}\n        data={data}\n        onDelete={onDelete}\n        onSelect={onSelect}\n        onAbort={onAbort}\n    />\n    return (\n        <Board className=\"board--light availability-timetable\"\n            title={titleTime}\n            titleAside={calendarNavigation(props.links)}\n            headerRight={constants.headerRight(props.links, props.onNewAvailability)}\n            headerMiddle={constants.headerMiddle()}\n            body={TableBody}\n            footer=\"\"\n        />\n    )\n}\n\nTableView.defaultProps = {\n\n}\n\nTableView.propTypes = {\n    timestamp: PropTypes.number,\n    links: PropTypes.object,\n    data: PropTypes.object,\n    availabilityList: PropTypes.array,\n    onNewAvailability: PropTypes.func,\n    onDelete: PropTypes.func.isRequired,\n    onSelect: PropTypes.func.isRequired,\n    onAbort: PropTypes.func.isRequired\n}\n\nexport default TableView\n\n","import React from 'react'\nimport moment from 'moment'\nimport PropTypes from 'prop-types' \n\nconst formatDate = date => {\n    const momentDate = moment(date)\n    return `${momentDate.format('DD.MM.YYYY')} um ${momentDate.format('HH:mm')} Uhr`\n} \n \nconst SaveBar = (props) => {\n    return (\n        <div ref={props.setSuccessRef} className=\"message message--success\">\n            Öffnungszeiten gespeichert, {formatDate(props.lastSave)}\n        </div>\n    )\n}\n\nSaveBar.propTypes = {\n    lastSave: PropTypes.oneOfType([\n        PropTypes.number, PropTypes.string\n    ]).isRequired,\n    setSuccessRef: PropTypes.func\n}\n\nexport default SaveBar\n","import React from 'react'\nimport PropTypes from 'prop-types'\n\nconst FormButtons = (props) => {\n    const { data, onCopy, onExclusion, onEditInFuture, onUpdateSingle, onDelete, selectedDate, hasConflicts } = props\n    const disabled = ((data && (! data.id || data.__modified === true)) || hasConflicts);\n    return (\n        <div className=\"body\">\n            <div className=\"form-actions\">\n                <button onClick={onDelete}\n                    title=\"Ausgewählte Öffnungszeit löschen\"\n                    className=\"button button--destructive button-delete\" disabled={disabled}>Löschen</button>\n                <button onClick={onCopy}\n                    title=\"Öffnungszeit kopieren und bearbeiten\"\n                    className=\"button button--diamond\" disabled={disabled}>Kopieren</button>\n                <button onClick={onExclusion}\n                    title=\"Ausnahme von dieser Öffnungszeit eintragen\"\n                    className=\"button button--diamond\" disabled={disabled || data.endDate == selectedDate}>Ausnahme</button>\n                <button onClick={onEditInFuture}\n                    title=\"Öffnungszeit ab diesem Tag ändern\"\n                    className=\"button button--diamond\" disabled={disabled || data.startDate == selectedDate}>Ab diesem Tag ändern</button> \n                <button onClick={onUpdateSingle}\n                    title=\"Öffnungszeit aktualisieren\"\n                    className=\"button button--diamond\" disabled={(data && !data.id) || hasConflicts}>Aktualisieren</button> \n            </div>\n        </div>\n    )\n}\n\nFormButtons.propTypes = {\n    data: PropTypes.object,\n    hasConflicts: PropTypes.bool,\n    onCopy: PropTypes.func,\n    onExclusion: PropTypes.func,\n    onEditInFuture: PropTypes.func,\n    onDelete: PropTypes.func,\n    onUpdateSingle: PropTypes.func,\n    selectedDate: PropTypes.number\n}\n\nexport default FormButtons\n","/* eslint-disable react/prop-types */\nimport React from 'react'\n\nconst noOp = () => { }\n\nconst SelectOption = ({ name, value, title }) => {\n    return (\n        <option {...{ value }} {...{ title }}>{name || value}</option>\n    )\n}\n\nconst SelectOptGroup = ({ label, options = [], selectedValue }) => {\n    return (\n        <optgroup {...{ label }}>{renderOptions(options, selectedValue)}</optgroup>\n    )\n}\n\nconst renderOptions = (options) => options.map((option, key) => <SelectOption key={key} {...option} {...{ key }} />)\nconst renderGroups = (groups) => groups.map((group, key) => <SelectOptGroup key={key} {...group} {...{ key }} />)\n\nexport const Select = ({ name, options = [], groups = [], value, onChange = noOp, attributes = {} }) => {\n    const onSelect = ev => onChange(name, ev.target.value)\n\n    return (\n        <select onChange={onSelect} {...{ name }} value={value} {...attributes} className=\"form-control\">\n            {renderGroups(groups)}\n            {renderOptions(options)}\n        </select>\n    )\n}\n","/* eslint-disable react/prop-types */\nimport React from 'react'\nimport PropTypes from 'prop-types'\nimport { noOp } from '../utils'\n\nexport const Checkbox = ({ name, value, label, checked = \"false\", disabled=false, onChange = noOp, attributes = {}, className = 'form-check-input' }) => {\n\n    const onInput = () => {\n        //ev.preventDefault()\n        onChange(name, !checked)\n    }\n\n    attributes.checked = (checked) ? \"checked\" : \"\";\n    return (\n        <label className=\"form-check-label\" {...{ label }}>\n            <input type=\"checkbox\" value={value || \"\"} {...{ name }} {...attributes} onChange={onInput} className={className} disabled={disabled} />\n            {label}\n        </label>\n    )\n}\n\nexport const CheckboxGroup = (props) => {\n    const toggle = (toggleValue) => {\n        const oldValue = props.value\n        const newValue = (oldValue.indexOf(toggleValue) > -1)\n            ? oldValue.filter(v => v !== toggleValue)\n            : oldValue.concat([toggleValue])\n\n        props.onChange(props.name, newValue)\n    }\n\n    return (\n        <span className={`checkbox--${props.name}`}>\n            {props.boxes.map((box, key) => {\n                const checked = props.value.indexOf(box.value) > -1\n                const className = `form-check${props.inline ? ' form-check-inline' : ''}`\n                return (\n                    <div key={key} className={className}>\n                        <Checkbox name={`${props.name}[]`}\n                            value={box.value || \"\"}\n                            label={box.label}\n                            checked={checked || \"\"}\n                            disabled={props.disabled}\n                            onChange={() => toggle(box.value)} />\n                    </div>\n                )\n            })}\n        </span>\n    )\n}\n\n\nCheckboxGroup.defaultProps = {\n    boxes: [],\n    value: []\n}\n\nCheckboxGroup.propTypes = {\n    boxes: PropTypes.array,\n    value: PropTypes.array\n}\n","import React from 'react'\nimport PropTypes from 'prop-types'\n\nimport moment from 'moment'\nimport { range } from '../lib/utils'\n\nconst padTwo = value => {\n    const strValue = `${value}`\n    return strValue.length >= 2 ? strValue : `0${strValue}`\n}\n\nconst renderTimeOption = (value, key) => {\n    return <option key={key} value={value}>{padTwo(value)}</option>\n}\n\nconst renderQuarterOption = (quarter, key) => {\n    return <option key={key} value={`q${quarter}`}>{padTwo(quarter)}</option>\n}\n\nconst renderHours = () => {\n    return range(0, 23).map(renderTimeOption)\n}\n\nconst renderMinutes = () => {\n    return range(0, 59).map(renderTimeOption)\n}\n\nconst renderQuarters = () => {\n    return range(0, 45, 15).map(renderQuarterOption)\n}\n\nconst TimePicker = (props) => {\n    const time = moment(props.value, props.format)\n\n    const onHourChange = ev => {\n        const newHour = parseInt(ev.target.value, 10)\n        props.onChange(time.clone().hour(newHour).format(props.format))\n    }\n\n    const onMinuteChange = ev => {\n        const newMinute = parseInt(ev.target.value.replace(/^q/, ''), 10)\n        props.onChange(time.clone().minute(newMinute).format(props.format))\n    }\n\n    const selectedHour = `${time.hour()}`\n    const minute = time.minute()\n    const minutePrefix = minute % 15 === 0 ? 'q' : ''\n    const selectedMinute = `${minutePrefix}${minute}`\n    const nameHour = props.name + '--hour'\n    const nameMinute = props.name + '--minute'\n\n    return (\n        <span className=\"timepicker\">\n            <select className=\"form-control\" name={nameHour} onChange={onHourChange} value={selectedHour}>\n                {renderHours()}\n            </select>\n            <span className=\"delimiter\">{\":\"}</span>\n            <select className=\"form-control\" name={nameMinute} onChange={onMinuteChange} value={selectedMinute}>\n                <optgroup>\n                    {renderQuarters()}\n                </optgroup>\n                <optgroup>\n                    {renderMinutes()}\n                </optgroup>\n            </select>\n        </span>\n    )\n}\n\nTimePicker.defaultProps = {\n    value: moment(),\n    format: 'HH:mm:ss',\n    onChange: () => {}\n}\n\nTimePicker.propTypes = {\n    name: PropTypes.string,\n    value: PropTypes.string,\n    format: PropTypes.string,\n    onChange: PropTypes.func\n}\n\nexport default TimePicker\n","/* eslint-disable react/prop-types */\nimport React from 'react'\n// import TimePicker from 'rc-time-picker'\nimport TimePicker from '../timePicker.js'\n\nconst TIME_FORMAT = 'HH:mm:ss'\n\nexport const Time = ({ name, value, onChange }) => {\n    const onPick = time => {\n        onChange(name, time)\n    }\n    return <TimePicker name={name} value={value} onChange={onPick} format={TIME_FORMAT}/>\n}\n","!function(e,t){\"object\"==typeof exports&&\"undefined\"!=typeof module?t(exports,require(\"react\"),require(\"prop-types\"),require(\"classnames\"),require(\"date-fns/isDate\"),require(\"date-fns/isValid\"),require(\"date-fns/format\"),require(\"date-fns/addMinutes\"),require(\"date-fns/addHours\"),require(\"date-fns/addDays\"),require(\"date-fns/addWeeks\")